    // ── CORRELATED subqueries: valid resolves, typo is loud ─────────────

    #[test]
    fn correlated_outer_reference_in_subquery_resolves() {
        // The subquery references the OUTER `users.id` (correlation): it must
        // resolve through the threaded outer scope, NOT error. This is the
        // existing correlated-scalar-subquery feature; it must not regress.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT users.name, \
             (SELECT accounts.balance FROM accounts WHERE accounts.user_id = users.id) AS bal \
             FROM users",
        )
        .expect("correlated reference resolves");
        assert_eq!(
            s.columns,
            vec![
                col("name", RustType::Text, false),
                col("bal", RustType::I32, true),
            ]
        );
    }

    #[test]
    fn correlated_outer_reference_in_where_subquery_resolves() {
        // A correlated reference inside a WHERE-clause subquery resolves too.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT name FROM users WHERE EXISTS \
             (SELECT 1 FROM accounts WHERE accounts.user_id = users.id)",
        )
        .expect("correlated EXISTS resolves");
        assert_eq!(s.columns, vec![col("name", RustType::Text, false)]);
        assert!(s.params.is_empty());
    }

    #[test]
    fn unknown_correlated_outer_reference_is_loud() {
        // `users.nonexistent` names a real OUTER relation but a column it
        // does not have: a found-relation/missing-column case that an outer
        // scope cannot rescue, so it is loud (not a fall-through).
        let err = shape(
            &[USERS, ACCOUNTS],
            "SELECT users.name, \
             (SELECT accounts.balance FROM accounts WHERE accounts.user_id = users.nonexistent) AS bal \
             FROM users",
        )
        .expect_err("unknown correlated column");
        assert_unknown_ref(err);
    }

