    #[test]
    fn param_in_any_operand_is_seen_and_loud_without_cast() {
        // `id = ANY($1)`: `$1` is an array param (e.g. int8[]), outside the
        // v1 scalar set, so it must carry an explicit cast — but it is SEEN,
        // never dropped.
        let err = shape(&[USERS], "SELECT name FROM users WHERE id = ANY($1)")
            .expect_err("ANY array param needs a cast");
        assert!(matches!(err, InferError::ParamCastRequired { .. }), "got: {err:?}");
    }

    #[test]
    fn param_in_any_array_constructor_types_from_text_column() {
        // `col = ANY(ARRAY[$1, $2])`: an explicit array CONSTRUCTOR of bare
        // placeholders. PostgreSQL resolves the unknown elements to `text`, so
        // the comparison succeeds — and the elements type to `text` — only when
        // the compared column is itself a text column. For a text column the
        // engine types each element to `Text`, identical to `col IN ($1, $2)`.
        for sql in [
            "SELECT name FROM users WHERE name = ANY(ARRAY[$1, $2])",
            "SELECT name FROM users WHERE name = ALL(ARRAY[$1, $2])",
            "SELECT name FROM users WHERE name = SOME(ARRAY[$1, $2])",
        ] {
            let s = shape(&[USERS], sql).expect("text column array-quantifier params");
            assert_eq!(s.params, vec![RustType::Text, RustType::Text], "sql `{sql}`");
        }
    }

    #[test]
    fn param_in_any_array_constructor_on_non_text_column_is_loud() {
        // For a NON-text column the bare-placeholder array constructor resolves
        // its elements to `text`, which PostgreSQL has no `int = text` /
        // `bigint = text` member operator for — it rejects the query. The engine
        // matches: the elements stay cast-required (loud), never typed to a shape
        // the server would reject.
        for sql in [
            "SELECT name FROM users WHERE id = ANY(ARRAY[$1])",
            "SELECT name FROM users WHERE age = ANY(ARRAY[$1, $2])",
        ] {
            let err = shape(&[USERS], sql)
                .expect_err("non-text column bare-placeholder array is cast-required");
            assert!(
                matches!(err, InferError::ParamCastRequired { .. }),
                "sql `{sql}`: got {err:?}"
            );
        }
    }

    #[test]
    fn param_in_any_array_cast_types_from_element_cast() {
        // `col = ANY(ARRAY[$1, $2]::T[])`: the array cast pins the element type to
        // `T`, so every element placeholder types to `T` regardless of the column
        // (PostgreSQL accepts a non-text column here through the cast).
        let s = shape(&[USERS], "SELECT name FROM users WHERE id = ANY(ARRAY[$1, $2]::int8[])")
            .expect("array cast pins int8 elements");
        assert_eq!(s.params, vec![RustType::I64, RustType::I64]);
        let s = shape(&[USERS], "SELECT name FROM users WHERE name = ANY(ARRAY[$1, $2]::text[])")
            .expect("array cast pins text elements");
        assert_eq!(s.params, vec![RustType::Text, RustType::Text]);
        let s = shape(&[ACCOUNTS], "SELECT id FROM accounts WHERE balance = ANY(ARRAY[$1]::int4[])")
            .expect("array cast pins int4 element");
        assert_eq!(s.params, vec![RustType::I32]);
    }

    #[test]
    fn param_as_any_array_constructor_left_operand_types_from_member_column() {
        // The reversed form `$1 = ANY(ARRAY[col])`: the array member is the
        // COLUMN, so PostgreSQL fixes the element type to that column's type and
        // the left placeholder types to it — for ANY column type, not only text.
        let s = shape(&[USERS], "SELECT name FROM users WHERE $1 = ANY(ARRAY[name])")
            .expect("left param from text member");
        assert_eq!(s.params, vec![RustType::Text]);
        let s = shape(&[USERS], "SELECT name FROM users WHERE $1 = ANY(ARRAY[id])")
            .expect("left param from bigint member");
        assert_eq!(s.params, vec![RustType::I64]);
        let s = shape(&[ACCOUNTS], "SELECT id FROM accounts WHERE $1 = ANY(ARRAY[balance])")
            .expect("left param from int member");
        assert_eq!(s.params, vec![RustType::I32]);
        // A column member also fixes the element type for OTHER placeholder
        // members and the left placeholder together.
        let s = shape(&[USERS], "SELECT name FROM users WHERE $1 = ANY(ARRAY[id, $2])")
            .expect("both params from the bigint column member");
        assert_eq!(s.params, vec![RustType::I64, RustType::I64]);
        let s = shape(&[USERS], "SELECT name FROM users WHERE name = ANY(ARRAY[bio, $1])")
            .expect("element param from the text column member");
        assert_eq!(s.params, vec![RustType::Text]);
    }

    #[test]
    fn param_in_uncast_subquery_clause_is_loud_not_dropped() {
        // A `$1` only inside a subquery's ORDER BY (no column context) is
        // SEEN by the whole-statement scan and fails closed, never dropped.
        let err = shape(
            &[USERS, ACCOUNTS],
            "SELECT name FROM users WHERE id IN \
             (SELECT user_id FROM accounts ORDER BY $1)",
        )
        .expect_err("subquery ORDER BY param without cast");
        assert!(matches!(err, InferError::ParamCastRequired { .. }), "got: {err:?}");
    }

