    // ── ITEM-E (1): set operations branch-merge nullability ─────────────

    #[test]
    fn union_branch_merges_nullability() {
        // users.name is NOT NULL; users.bio is nullable. A UNION column is
        // nullable if nullable in EITHER branch.
        let s = shape(
            &[USERS],
            "SELECT name FROM users UNION SELECT bio FROM users",
        )
        .expect("ok");
        assert_eq!(s.columns, vec![col("name", RustType::Text, true)]);
    }

    #[test]
    fn union_all_not_null_both_branches_stays_not_null() {
        let s = shape(
            &[USERS],
            "SELECT name FROM users UNION ALL SELECT name FROM users",
        )
        .expect("ok");
        assert_eq!(s.columns, vec![col("name", RustType::Text, false)]);
    }

    #[test]
    fn union_mismatched_column_count_is_loud() {
        let err = shape(
            &[USERS],
            "SELECT id, name FROM users UNION SELECT name FROM users",
        )
        .expect_err("column count differs");
        assert!(
            matches!(err, InferError::SetOpArmArityMismatch { left: 2, right: 1, .. }),
            "got: {err:?}"
        );
    }

    #[test]
    fn union_mismatched_types_is_loud() {
        let err = shape(
            &[USERS],
            "SELECT id FROM users UNION SELECT name FROM users",
        )
        .expect_err("int8 vs text branches");
        assert!(matches!(err, InferError::CastRequired { .. }), "got: {err:?}");
    }

    #[test]
    fn intersect_and_except_branch_merge() {
        for op in ["INTERSECT", "EXCEPT"] {
            let sql = format!("SELECT name FROM users {op} SELECT bio FROM users");
            let s = shape(&[USERS], &sql).expect("ok");
            assert_eq!(s.columns, vec![col("name", RustType::Text, true)], "op={op}");
        }
    }

    #[test]
    fn union_integer_widths_widen_to_wider() {
        // users.id is int8, accounts.id is int4. PostgreSQL accepts the UNION
        // and widens to bigint; the result column takes the wider i64. The
        // output name follows the LEFT branch.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT id FROM users UNION SELECT id FROM accounts",
        )
        .expect("integer widths widen");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn union_int4_left_int8_right_widens_to_i64() {
        // users.age is int4 (nullable), accounts.user_id is int8 (NOT NULL).
        // The wider type is i64; nullability OR-merges to nullable.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT age FROM users UNION SELECT user_id FROM accounts",
        )
        .expect("int4 left widens to i64");
        assert_eq!(s.columns, vec![col("age", RustType::I64, true)]);
    }

    #[test]
    fn intersect_and_except_integer_widths_widen() {
        // The same widening applies to INTERSECT and EXCEPT, matching PG.
        for op in ["INTERSECT", "EXCEPT"] {
            let sql = format!("SELECT id FROM users {op} SELECT id FROM accounts");
            let s = shape(&[USERS, ACCOUNTS], &sql).expect("ok");
            assert_eq!(s.columns, vec![col("id", RustType::I64, false)], "op={op}");
        }
    }

    #[test]
    fn union_text_vs_int_has_no_common_type_and_is_loud() {
        // text and int8 have no common type; PostgreSQL rejects the UNION and
        // so does the engine — the widening only applies to integer widths.
        let err = shape(
            &[USERS],
            "SELECT name FROM users UNION SELECT id FROM users",
        )
        .expect_err("text vs int has no common type");
        assert!(matches!(err, InferError::CastRequired { .. }), "got: {err:?}");
    }

    // ── no-common-type DIAGNOSTIC reads as clean English ─────────────────
    // The CastRequired template wraps `{what}` as a noun phrase
    // ("the type/nullability of {what} cannot be inferred from the schema.
    // Add an explicit cast …"). These assert the FULLY RENDERED message for a
    // UNION / COALESCE / CASE no-common-type, so a `{what}` that ever again
    // smuggles an imperative sentence ("… Cast both branches to one type
    // cannot be inferred …") would fail loudly here.

    #[test]
    fn union_no_common_type_message_reads_cleanly() {
        let err = shape(&[USERS], "SELECT name FROM users UNION SELECT id FROM users")
            .expect_err("text vs int has no common type");
        let rendered = err.to_string();
        assert_eq!(
            rendered,
            "the type/nullability of output column `name` of a UNION whose \
             branches have incompatible types (`String` vs `i64`) with no \
             common type cannot be inferred from the schema. Add an explicit \
             cast in the SQL (e.g. `expr::int4`) so the output column has a \
             known type — this is never guessed."
        );
        // The malformed-message regression: a leftover imperative spliced
        // mid-sentence ahead of "cannot be inferred".
        assert!(
            !rendered.contains("Cast both branches to one type cannot be inferred"),
            "imperative smuggled into the noun phrase: {rendered}"
        );
    }

    #[test]
    fn coalesce_no_common_type_message_reads_cleanly() {
        let err = shape(&[USERS], "SELECT COALESCE(name, age) AS b FROM users")
            .expect_err("text vs int has no common type");
        let rendered = err.to_string();
        assert_eq!(
            rendered,
            "the type/nullability of a COALESCE whose branches have \
             incompatible types (`String` and `i32`) with no common type \
             cannot be inferred from the schema. Add an explicit cast in the \
             SQL (e.g. `expr::int4`) so the output column has a known type — \
             this is never guessed."
        );
        assert!(
            !rendered.contains("one type cannot be inferred"),
            "imperative smuggled into the noun phrase: {rendered}"
        );
    }

    #[test]
    fn case_no_common_type_message_reads_cleanly() {
        let err = shape(
            &[USERS],
            "SELECT CASE WHEN age > 18 THEN 'adult' ELSE 0 END AS k FROM users",
        )
        .expect_err("text vs int has no common type");
        let rendered = err.to_string();
        assert_eq!(
            rendered,
            "the type/nullability of a CASE whose branches have incompatible \
             types (`String` and `i32`) with no common type cannot be \
             inferred from the schema. Add an explicit cast in the SQL (e.g. \
             `expr::int4`) so the output column has a known type — this is \
             never guessed."
        );
        assert!(
            !rendered.contains("one type cannot be inferred"),
            "imperative smuggled into the noun phrase: {rendered}"
        );
    }

    // ── ITEM-E (2): scalar subquery in SELECT ───────────────────────────

    #[test]
    fn scalar_subquery_in_select_is_optional() {
        // A scalar subquery yields at most one row, so its value is Option.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT users.name, \
             (SELECT accounts.balance FROM accounts WHERE accounts.user_id = users.id) AS bal \
             FROM users",
        )
        .expect("ok");
        assert_eq!(
            s.columns,
            vec![
                col("name", RustType::Text, false),
                // balance is NOT NULL in the catalog, but a scalar subquery
                // may match no row, so the projected value is nullable.
                col("bal", RustType::I32, true),
            ]
        );
    }

    #[test]
    fn scalar_subquery_multiple_columns_is_loud() {
        let err = shape(
            &[USERS, ACCOUNTS],
            "SELECT (SELECT id, balance FROM accounts) AS x FROM users",
        )
        .expect_err("scalar subquery must be one column");
        // A subquery used as a single projected value must return exactly one
        // column (PostgreSQL: "subquery must return only one column"); the
        // position check names the expected/found counts precisely.
        assert!(
            matches!(
                err,
                InferError::SubqueryArityMismatch {
                    scalar: true,
                    expected: 1,
                    found: 2,
                }
            ),
            "got: {err:?}"
        );
    }

