    fn cte_resolves_in_nested_exists_subquery() {
        shape(
            &[USERS],
            "WITH a AS (SELECT id FROM users) SELECT id FROM a WHERE EXISTS (SELECT 1 FROM a)",
        )
        .expect("outer CTE resolves in a nested EXISTS subquery");
    }

