    fn cte_resolves_in_projection_scalar_subquery() {
        shape(
            &[USERS],
            "WITH a AS (SELECT id FROM users) SELECT (SELECT count(*) FROM a) AS n",
        )
        .expect("outer CTE resolves in a projected scalar subquery");
    }

