    fn cte_resolves_in_scalar_comparison_subquery() {
        shape(
            &[USERS],
            "WITH a AS (SELECT id FROM users) SELECT id FROM a \
             WHERE id = (SELECT max(id) FROM a)",
        )
        .expect("outer CTE resolves in a scalar comparison subquery");
    }

