    // ── function name posture (typed or fail-closed, never silent-wrong) ─

    #[test]
    fn unknown_function_name_is_loud_cast_required() {
        // An unmodeled function name is a loud CastRequired (never a silent
        // wrong type); its column ARGS are still existence-checked.
        let err = shape(&[USERS], "SELECT no_such_fn(name) FROM users")
            .expect_err("unknown function");
        assert!(matches!(err, InferError::CastRequired { .. }), "got: {err:?}");
    }

