    fn typo_column_inside_function_arg_is_loud() {
        assert_unknown_column("SELECT lower(nope) FROM users");
    }

    // ── param typing inside every subquery body the existence pass covers ─

    #[test]
    fn param_in_from_derived_table_body_is_typed() {
        // `$1` lives in a FROM-clause derived table's WHERE; it must type from
        // the derived body's own scope (`users.age` -> int4), exactly like a
        // WHERE-clause subquery does — never a spurious cast-required.
        let s = shape(
            &[USERS],
            "SELECT t.id FROM (SELECT id FROM users WHERE age = $1) t",
        )
        .expect("ok");
        assert_eq!(s.params, vec![RustType::I32]);
    }

    #[test]
    fn param_in_cte_body_is_typed() {
        // `$1` lives in a CTE body's WHERE; it must type from the CTE body's
        // own scope (`users.age` -> int4).
        let s = shape(
            &[USERS],
            "WITH c AS (SELECT id FROM users WHERE age = $1) SELECT c.id FROM c",
        )
        .expect("ok");
        assert_eq!(s.params, vec![RustType::I32]);
    }

    #[test]
    fn param_in_projection_scalar_subquery_is_typed() {
        // `$1` lives in a projected scalar subquery's WHERE; it must type from
        // that subquery's own scope (`users.age` -> int4).
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT (SELECT id FROM users WHERE age = $1) AS x FROM accounts",
        )
        .expect("ok");
        assert_eq!(s.params, vec![RustType::I32]);
    }

    #[test]
    fn param_in_correlated_scalar_subquery_is_typed() {
        // A correlated projected scalar subquery: `a.user_id = u.id`
        // references the OUTER `users u`, and `$1` types from the INNER
        // `accounts.balance` (int4). Both the correlation and the param type
        // must resolve.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT (SELECT balance FROM accounts a \
             WHERE a.user_id = u.id AND a.balance > $1 LIMIT 1) AS b FROM users u",
        )
        .expect("ok");
        assert_eq!(s.params, vec![RustType::I32]);
    }

    #[test]
    fn param_in_derived_body_limit_types_to_i64() {
        // A `$1` in a derived body's own LIMIT is a bigint count, exactly as on
        // any query (PostgreSQL reports parameter_types {bigint}), so it types
        // to I64 directly — the descent walks the nested query's own LIMIT
        // rather than leaving the param untyped to fail closed.
        let s = shape(
            &[USERS],
            "SELECT t.id FROM (SELECT id FROM users LIMIT $1) t",
        )
        .expect("derived-body LIMIT param types to i64");
        assert_eq!(s.params, vec![RustType::I64]);
    }

    #[test]
    fn untypeable_param_in_derived_body_still_fails_closed() {
        // A `$1` in a derived body with NO column context (here on the far side
        // of an arithmetic sub-expression, not a count clause) has no type to
        // infer, so it must still fail closed loudly — the descent never
        // silently drops or mistypes it.
        let err = shape(
            &[USERS],
            "SELECT t.id FROM (SELECT id FROM users WHERE age = age + $1) t",
        )
        .expect_err("derived-body arithmetic param needs a cast");
        assert!(matches!(err, InferError::ParamCastRequired { .. }), "got: {err:?}");
    }

    // ── INSERT column-list vs source-row arity (loud both directions) ────

    #[test]
    fn insert_too_few_literal_values_is_loud() {
        // `(id, name)` names two columns but the row supplies one literal.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1) RETURNING id",
        )
        .expect_err("too few values");
        match err {
            InferError::InsertArityMismatch { columns, values } => {
                assert_eq!(columns, 2);
                assert_eq!(values, 1);
            }
            other => panic!("wrong error: {other:?}"),
        }
    }

    #[test]
    fn insert_too_many_literal_values_is_loud() {
        // `(id)` names one column but the row supplies two literals.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id) VALUES (1, 2) RETURNING id",
        )
        .expect_err("too many values");
        match err {
            InferError::InsertArityMismatch { columns, values } => {
                assert_eq!(columns, 1);
                assert_eq!(values, 2);
            }
            other => panic!("wrong error: {other:?}"),
        }
    }

    #[test]
    fn insert_select_arity_mismatch_is_loud() {
        // `(id, name)` names two columns but the source SELECT projects one.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) SELECT id FROM users RETURNING id",
        )
        .expect_err("INSERT ... SELECT arity mismatch");
        match err {
            InferError::InsertArityMismatch { columns, values } => {
                assert_eq!(columns, 2);
                assert_eq!(values, 1);
            }
            other => panic!("wrong error: {other:?}"),
        }
    }

    #[test]
    fn insert_matching_literal_arity_is_ok() {
        // Two columns, two literal values -> accepted.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') RETURNING id",
        )
        .expect("ok");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
        assert!(s.params.is_empty());
    }

    #[test]
    fn insert_matching_arity_with_params_still_types() {
        // Matching arity with placeholders still types each `$N` by position.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) RETURNING id",
        )
        .expect("ok");
        assert_eq!(s.params, vec![RustType::I64, RustType::Text]);
    }

    #[test]
    fn insert_select_matching_arity_is_ok() {
        // Two columns, source SELECT projects two -> accepted.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) SELECT id, name FROM users RETURNING id",
        )
        .expect("ok");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    // ── FIX-1: no-column-list INSERT arity (silent-accept holes closed) ──

    #[test]
    fn insert_no_column_list_too_many_values_is_loud() {
        // No explicit column list -> the implicit target is the 4-column
        // `users` table. A row of 5 values exceeds it; PostgreSQL rejects
        // "INSERT has more expressions than target columns". It must be loud,
        // never a silently-accepted over-long insert.
        match shape(
            &[USERS],
            "INSERT INTO users VALUES (1, 2, 3, 4, 5) RETURNING id",
        ) {
            Err(InferError::InsertTooManyValues {
                table_columns: 4,
                values: 5,
            }) => {}
            other => panic!("expected InsertTooManyValues {{4, 5}}, got: {other:?}"),
        }
    }

    #[test]
    fn insert_no_column_list_inconsistent_multirow_is_loud() {
        // Multi-row VALUES with no column list whose rows differ in length —
        // PostgreSQL rejects "VALUES lists must all be the same length". A
        // purely structural rule; it must be loud even though both rows are
        // within the table's column count.
        match shape(
            &[USERS],
            "INSERT INTO users VALUES (1, 2, 3, 4), (5, 6) RETURNING id",
        ) {
            Err(InferError::ValuesRowsRagged {
                first: 4,
                offending: 2,
            }) => {}
            other => panic!("expected ValuesRowsRagged {{4, 2}}, got: {other:?}"),
        }
    }

    #[test]
    fn insert_no_column_list_too_few_values_is_accepted() {
        // A row SHORTER than the table's column count is valid — PostgreSQL
        // fills the omitted trailing columns with their defaults. It must NOT
        // be false-rejected. Both a single value and a trailing-omitted row.
        shape(&[USERS], "INSERT INTO users VALUES (1) RETURNING id")
            .expect("a shorter row fills trailing defaults — valid");
        shape(&[USERS], "INSERT INTO users VALUES (1, 'a', 'b') RETURNING id")
            .expect("trailing-omitted columns take their defaults — valid");
    }

    #[test]
    fn insert_no_column_list_matching_arity_is_accepted() {
        // A row with exactly the table's column count is accepted.
        shape(
            &[USERS],
            "INSERT INTO users VALUES (1, 'a', 'b', 2) RETURNING id",
        )
        .expect("a full-arity row is valid");
    }

    #[test]
    fn insert_no_column_list_select_too_many_is_loud() {
        // INSERT ... SELECT with no column list whose projection exceeds the
        // table arity is loud.
        match shape(
            &[USERS],
            "INSERT INTO users SELECT id, name, bio, age, id FROM users RETURNING id",
        ) {
            Err(InferError::InsertTooManyValues {
                table_columns: 4,
                values: 5,
            }) => {}
            other => panic!("expected InsertTooManyValues {{4, 5}}, got: {other:?}"),
        }
    }

    #[test]
    fn insert_no_column_list_select_too_few_is_accepted() {
        // INSERT ... SELECT with no column list whose projection is shorter
        // than the table arity fills trailing defaults — valid.
        shape(
            &[USERS],
            "INSERT INTO users SELECT id FROM users RETURNING id",
        )
        .expect("a shorter SELECT projection fills trailing defaults — valid");
    }

    #[test]
    fn insert_explicit_column_list_arity_behavior_is_unchanged() {
        // The explicit-column-list path keeps its exact-match behavior in both
        // directions, and a later-row mismatch is still InsertArityMismatch
        // (the per-row equality check fires before the same-length rule).
        match shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1) RETURNING id",
        ) {
            Err(InferError::InsertArityMismatch {
                columns: 2,
                values: 1,
            }) => {}
            other => panic!("expected InsertArityMismatch {{2, 1}}, got: {other:?}"),
        }
        match shape(
            &[USERS],
            "INSERT INTO users (id) VALUES (1, 2) RETURNING id",
        ) {
            Err(InferError::InsertArityMismatch {
                columns: 1,
                values: 2,
            }) => {}
            other => panic!("expected InsertArityMismatch {{1, 2}}, got: {other:?}"),
        }
        match shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a'), (2) RETURNING id",
        ) {
            Err(InferError::InsertArityMismatch {
                columns: 2,
                values: 1,
            }) => {}
            other => panic!("expected InsertArityMismatch {{2, 1}}, got: {other:?}"),
        }
        shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') RETURNING id",
        )
        .expect("matching explicit-list arity is valid");
    }

    // ── FIX-2: merged USING / NATURAL column resolves unqualified ────────

    #[test]
    fn using_merged_column_unqualified_resolves_to_one_column() {
        // `SELECT id FROM users JOIN accounts USING (id)` — PostgreSQL merges
        // the USING column into one, so an unqualified `id` is unambiguous and
        // valid (it was previously a false-reject AmbiguousColumn). The merged
        // type is the common type of i64 (users.id) and i32 (accounts.id) =
        // i64 (the wider); both sides are PK NOT NULL, so non-null.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT id FROM users JOIN accounts USING (id)",
        )
        .expect("merged USING column is unambiguous");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn natural_join_common_column_unqualified_resolves_to_one_column() {
        // A NATURAL join merges every common column; `id` is common to users
        // and accounts, so an unqualified `id` resolves to one merged column.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT id FROM users NATURAL JOIN accounts",
        )
        .expect("merged NATURAL common column is unambiguous");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn merged_column_qualified_reference_still_resolves_per_relation() {
        // A QUALIFIED reference to a merged column still resolves to that
        // relation's own column (with that relation's own type), unaffected by
        // the merge: users.id is i64, accounts.id is i32.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT users.id AS uid, accounts.id AS aid FROM users JOIN accounts USING (id)",
        )
        .expect("qualified merged-column references resolve per relation");
        assert_eq!(
            s.columns,
            vec![
                col("uid", RustType::I64, false),
                col("aid", RustType::I32, false),
            ]
        );
    }

    #[test]
    fn merged_column_under_left_join_follows_left_base_nullability() {
        // `users LEFT JOIN accounts USING (id)` — a LEFT JOIN's merged key
        // follows the LEFT base column's nullability (the left row is preserved,
        // its key supplies the merged value). `users.id` is a NOT NULL primary
        // key, so the merged column is NOT NULL even though the right side is
        // outer-join-nullable.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT id FROM users LEFT JOIN accounts USING (id)",
        )
        .expect("merged column under LEFT JOIN is valid");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn plain_join_shared_name_is_still_ambiguous() {
        // A shared column name that is NOT a USING / NATURAL key (an
        // accidental same-name on two plain-joined tables) is STILL a loud
        // AmbiguousColumn — the merge only covers join keys.
        match shape(
            &[USERS, ACCOUNTS],
            "SELECT id FROM users INNER JOIN accounts ON accounts.user_id = users.id",
        ) {
            Err(InferError::AmbiguousColumn(name)) if name == "id" => {}
            other => panic!("expected AmbiguousColumn(\"id\"), got: {other:?}"),
        }
    }

    #[test]
    fn natural_join_non_merged_columns_remain_per_relation() {
        // After a NATURAL join, the non-merged columns are still reachable
        // unqualified from their single owning relation (name from users,
        // balance from accounts) — the merge does not hide them.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT id, name, balance FROM users NATURAL JOIN accounts",
        )
        .expect("non-merged columns remain reachable");
        assert_eq!(
            s.columns,
            vec![
                col("id", RustType::I64, false),
                col("name", RustType::Text, false),
                col("balance", RustType::I32, false),
            ]
        );
    }

    // ── cross-chain merge masking — a merge over one FROM chain must NOT ──
    //    silence a same-named column on a SEPARATE comma-joined chain ─────

    #[test]
    fn crosschain_merge_does_not_mask_separate_chain_column() {
        // `SELECT id FROM users, accounts a JOIN accounts b USING (id)` — the
        // USING merge coalesces only a.id/b.id (one candidate); users.id on the
        // independent comma chain is a SECOND candidate. PostgreSQL rejects the
        // unqualified `id` as ambiguous, so this engine must too — a merge may
        // not silently mask a column from another FROM item.
        match shape(
            &[USERS, ACCOUNTS],
            "SELECT id FROM users, accounts a JOIN accounts b USING (id)",
        ) {
            Err(InferError::AmbiguousColumn(name)) if name == "id" => {}
            other => panic!("expected AmbiguousColumn(\"id\"), got: {other:?}"),
        }
    }

    #[test]
    fn crosschain_merge_mask_symmetric_ordering_is_also_ambiguous() {
        // The symmetric ordering (`merge chain FIRST, lone relation SECOND`)
        // resolves to the same count and must be equally ambiguous — the rule
        // is order-independent.
        match shape(
            &[USERS, ACCOUNTS],
            "SELECT id FROM accounts a JOIN accounts b USING (id), users",
        ) {
            Err(InferError::AmbiguousColumn(name)) if name == "id" => {}
            other => panic!("expected AmbiguousColumn(\"id\"), got: {other:?}"),
        }
    }

    #[test]
    fn single_chain_merge_stays_unambiguous_after_crosschain_fix() {
        // The single-chain merge that the cross-chain fix must NOT regress: the
        // merge spans both relations (the only candidate), so unqualified `id`
        // stays valid and resolves to the wider common type (i64).
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT id FROM users JOIN accounts USING (id)",
        )
        .expect("single-chain merge is still the lone candidate");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn chained_using_folds_into_one_merged_column() {
        // `a JOIN b USING (id) JOIN c USING (id)` — the second USING merges the
        // already-merged `id` with c.id, folding c into the SAME running merged
        // column (consumed = {a, b, c}). PostgreSQL accepts the unqualified
        // `id`, so this engine must too: the chain is ONE candidate, not
        // {a,b}-merge + lone-c. All three are accounts.id (i32).
        let s = shape(
            &[ACCOUNTS],
            "SELECT id FROM accounts a JOIN accounts b USING (id) JOIN accounts c USING (id)",
        )
        .expect("a chained USING folds into one merged column");
        assert_eq!(s.columns, vec![col("id", RustType::I32, false)]);
    }

    // ── USING / NATURAL merged-column nullability: per-side + join type ─────
    //
    // A merged column is `COALESCE(left.k, right.k)` over an equi-join key NULL
    // never satisfies, so the merged key's nullability follows each side's
    // nullability and the join type. When neither side carries an outer-join
    // promotion (the combos here), that per-side nullability IS the base
    // nullability — the rule below, verified live against PostgreSQL by
    // EXECUTION across all 12 (join x base-nullability) combos:
    //   INNER -> NOT NULL always;
    //   LEFT  -> nullable iff the LEFT base column is nullable;
    //   RIGHT -> nullable iff the RIGHT base column is nullable;
    //   FULL  -> nullable iff EITHER base column is nullable.
    // (A side that ALREADY carries a promotion — from an earlier chain join or a
    // nested inner outer join — flows that into the preserved merged value; see
    // `merged_left_contributor_promoted_by_earlier_join_is_nullable` and
    // `merged_right_contributor_with_inner_outer_join_is_nullable`.)
    // Both sides of each merge share a column NAME but neither is a primary key,
    // so the merge is a real USING/NATURAL coalesce (not a PK-determined column).

    // Two tables sharing a NULLABLE column `k`.
    const NN_A: &str = "CREATE TABLE nn_a (k INT, lonly INT)";
    const NN_B: &str = "CREATE TABLE nn_b (k INT, ronly INT)";
    // Two tables sharing a NOT NULL non-PK column `k`.
    const PK_A: &str = "CREATE TABLE pk_a (k INT NOT NULL, lonly INT)";
    const PK_B: &str = "CREATE TABLE pk_b (k INT NOT NULL, ronly INT)";

    /// Assert the merged `k` of a `<left> <join> <right> USING (k)` query has
    /// the expected nullability. The two relations are given by their DDL.
    fn merged_k_nullable(left_ddl: &str, right_ddl: &str, join: &str, expected: bool) {
        let left_name = left_ddl.split_whitespace().nth(2).expect("table name");
        let right_name = right_ddl.split_whitespace().nth(2).expect("table name");
        let sql = format!("SELECT k FROM {left_name} {join} JOIN {right_name} USING (k)");
        let s = shape(&[left_ddl, right_ddl], &sql).expect("merged USING column query is valid");
        assert_eq!(
            s.columns,
            vec![col("k", RustType::I32, expected)],
            "query: {sql}"
        );
    }

    #[test]
    fn merged_using_inner_both_nullable_is_not_null() {
        // The over-nullability defect's primary case: INNER JOIN with BOTH base
        // columns nullable. The merged key is the matched equal value, present on
        // both sides, so it is NOT NULL — typing it Option<T> would force a
        // useless unwrap. (Live PG: `k IS NULL` is always false.)
        merged_k_nullable(NN_A, NN_B, "INNER", false);
    }

    #[test]
    fn merged_using_full_both_not_null_is_not_null() {
        // The over-nullability defect's second case: FULL JOIN with BOTH base
        // columns NOT NULL. An unmatched row's key is the present NOT NULL value
        // from its own side, so the merged key is never NULL. (Live PG: always
        // false.)
        merged_k_nullable(PK_A, PK_B, "FULL", false);
    }

    #[test]
    fn merged_using_twelve_join_base_combos() {
        // All 12 (join x base-nullability) combos, each cross-checked live.
        // (left_ddl, right_ddl, join, expected merged-k nullable)
        let cases: &[(&str, &str, &str, bool)] = &[
            // Both nullable.
            (NN_A, NN_B, "INNER", false),
            (NN_A, NN_B, "LEFT", true),   // left base nullable
            (NN_A, NN_B, "RIGHT", true),  // right base nullable
            (NN_A, NN_B, "FULL", true),   // either base nullable
            // Both NOT NULL.
            (PK_A, PK_B, "INNER", false),
            (PK_A, PK_B, "LEFT", false),  // left base not null
            (PK_A, PK_B, "RIGHT", false), // right base not null
            (PK_A, PK_B, "FULL", false),  // neither base nullable
            // Left nullable, right NOT NULL.
            (NN_A, PK_B, "INNER", false),
            (NN_A, PK_B, "LEFT", true),   // left base nullable
            (NN_A, PK_B, "RIGHT", false), // right base not null
            (NN_A, PK_B, "FULL", true),   // left base nullable
        ];
        for (left, right, join, expected) in cases {
            merged_k_nullable(left, right, join, *expected);
        }
    }

    #[test]
    fn merged_using_right_nullable_combos() {
        // The right-nullable-only side of the matrix (left NOT NULL, right
        // nullable): RIGHT and FULL pick up the right base nullability, LEFT does
        // not, INNER never does.
        merged_k_nullable(PK_A, NN_B, "INNER", false);
        merged_k_nullable(PK_A, NN_B, "LEFT", false); // left base not null
        merged_k_nullable(PK_A, NN_B, "RIGHT", true); // right base nullable
        merged_k_nullable(PK_A, NN_B, "FULL", true);  // right base nullable
    }

    #[test]
    fn merged_natural_follows_the_same_base_join_rule() {
        // NATURAL merges every common column by the identical rule. `k` is the
        // only common column of nn_a/nn_b (lonly/ronly differ).
        let s = shape(&[NN_A, NN_B], "SELECT k FROM nn_a NATURAL INNER JOIN nn_b")
            .expect("natural inner both-nullable is valid");
        assert_eq!(s.columns, vec![col("k", RustType::I32, false)]); // INNER -> NOT NULL
        let s = shape(&[PK_A, PK_B], "SELECT k FROM pk_a NATURAL FULL JOIN pk_b")
            .expect("natural full both-not-null is valid");
        assert_eq!(s.columns, vec![col("k", RustType::I32, false)]); // FULL not null
        let s = shape(&[NN_A, PK_B], "SELECT k FROM nn_a NATURAL LEFT JOIN pk_b")
            .expect("natural left left-nullable is valid");
        assert_eq!(s.columns, vec![col("k", RustType::I32, true)]); // LEFT -> left base nullable
    }

    #[test]
    fn merged_using_chained_follows_per_step_join_rule() {
        // A chained USING folds each step per its own join type, with the running
        // merged column's current nullability as the left base. `nn_a INNER
        // nn_b` is NOT NULL (inner); folding `FULL nn_c(nullable)` makes it
        // nullable (either side). Cross-checked live.
        const NN_C: &str = "CREATE TABLE nn_c (k INT, conly INT)";
        let s = shape(
            &[NN_A, NN_B, NN_C],
            "SELECT k FROM nn_a JOIN nn_b USING (k) FULL JOIN nn_c USING (k)",
        )
        .expect("chained inner-then-full merge is valid");
        assert_eq!(s.columns, vec![col("k", RustType::I32, true)]);
        // All-INNER chain over NOT NULL sides stays NOT NULL at every step.
        let s = shape(
            &[PK_A, PK_B],
            "SELECT k FROM pk_a JOIN pk_b USING (k) JOIN pk_a AS pk_c USING (k)",
        )
        .expect("chained inner over not-null stays valid");
        assert_eq!(s.columns, vec![col("k", RustType::I32, false)]);
    }

    #[test]
    fn crosschain_merge_mask_is_loud_in_exists_and_typed_paths() {
        // The candidate count is shared by the typed resolver AND the
        // existence-only (cast) resolver, so an unqualified merge-masked column
        // is ambiguous in BOTH — a cast over it must not silently accept what
        // the typed path rejects.
        match shape(
            &[USERS, ACCOUNTS],
            "SELECT CAST(id AS BIGINT) FROM users, accounts a JOIN accounts b USING (id)",
        ) {
            Err(InferError::AmbiguousColumn(name)) if name == "id" => {}
            other => panic!("expected AmbiguousColumn(\"id\") in cast path, got: {other:?}"),
        }
    }

    // ── FIX-3: regression corpus — no-col-list arity + merged column ─────

    #[test]
    fn corpus_no_column_list_arity_and_merged_column_two_way() {
        // LOUD direction: the silent-accept holes (no-col over-long, no-col
        // ragged multi-row) and the still-genuine ambiguity must each fail
        // closed; never a silently-accepted insert / column.
        let loud: &[(&[&str], &str, &str)] = &[
            (
                &[USERS],
                "INSERT INTO users VALUES (1, 2, 3, 4, 5) RETURNING id",
                "no-col-list-over-long",
            ),
            (
                &[USERS],
                "INSERT INTO users VALUES (1, 2, 3, 4), (5, 6) RETURNING id",
                "no-col-list-inconsistent-multirow",
            ),
            (
                &[USERS, ACCOUNTS],
                "SELECT id FROM users INNER JOIN accounts ON accounts.user_id = users.id",
                "plain-join-shared-name-still-ambiguous",
            ),
            (
                &[USERS, ACCOUNTS],
                "SELECT id FROM users, accounts a JOIN accounts b USING (id)",
                "crosschain-merge-mask-lone-first",
            ),
            (
                &[USERS, ACCOUNTS],
                "SELECT id FROM accounts a JOIN accounts b USING (id), users",
                "crosschain-merge-mask-merge-first",
            ),
        ];
        for (ddl, sql, name) in loud {
            match shape(ddl, sql) {
                Err(InferError::InsertTooManyValues { .. })
                | Err(InferError::ValuesRowsRagged { .. })
                | Err(InferError::AmbiguousColumn(_)) => {}
                Err(other) => panic!("`{name}` gave the wrong error: {other:?}\n  SQL: {sql}"),
                Ok(_) => panic!("`{name}` was SILENTLY ACCEPTED (forbidden hole)\n  SQL: {sql}"),
            }
        }
        // VALID direction: a no-col-list too-few row (defaults fill the rest)
        // and the merged USING / NATURAL unqualified references must each be
        // accepted; never a false-reject.
        let ok: &[(&[&str], &str, &str)] = &[
            (
                &[USERS],
                "INSERT INTO users VALUES (1) RETURNING id",
                "no-col-list-too-few-defaults",
            ),
            (
                &[USERS, ACCOUNTS],
                "SELECT id FROM users JOIN accounts USING (id)",
                "merged-USING-unqualified",
            ),
            (
                &[USERS, ACCOUNTS],
                "SELECT id FROM users NATURAL JOIN accounts",
                "merged-NATURAL-unqualified",
            ),
            (
                &[ACCOUNTS],
                "SELECT id FROM accounts a JOIN accounts b USING (id) JOIN accounts c USING (id)",
                "chained-USING-folds-to-one-candidate",
            ),
        ];
        for (ddl, sql, name) in ok {
            if let Err(err) = shape(ddl, sql) {
                panic!("`{name}` was wrongly REJECTED (false reject): {err:?}\n  SQL: {sql}");
            }
        }
    }

    // ── USING/NATURAL merged column over an OUTER-JOIN-PROMOTED contributor ──
    //
    // A merged key is `COALESCE(left.k, right.k)` over an equi-join key. The
    // BASE-nullability rule above is right ONLY when a side's promotion comes
    // from THIS join (which null-extends the side the OTHER side then supplies).
    // A side promoted by an EARLIER chain join, or by a nested outer join it is
    // built from, is DIFFERENT: this join PRESERVES that side, so its already-
    // accumulated NULLs flow straight into the merged key. Inferring such a
    // merged key NOT NULL is UNSOUND — a real server NULL then hits
    // `DecodeError::NullInNonNullColumn` on a valid query. Every case below was
    // reproduced live against PostgreSQL (the merged key returns an actual NULL).
    //
    // Two tables sharing a NOT NULL non-PK column `bk`, plus a join-key table.
    const OJ_A: &str = "CREATE TABLE oj_a (j INT NOT NULL, x INT)";
    const OJ_B: &str = "CREATE TABLE oj_b (j INT NOT NULL, bk INT NOT NULL, y INT)";
    const OJ_C: &str = "CREATE TABLE oj_c (bk INT NOT NULL, z INT)";
    const OJ_X: &str = "CREATE TABLE oj_x (bk INT NOT NULL, w INT)";

    #[test]
    fn merged_left_contributor_promoted_by_earlier_join_is_nullable() {
        // `oj_b` is null-extended by the first LEFT JOIN, then its NOT NULL `bk`
        // is the PRESERVED-left side of a second LEFT JOIN merge — so the merged
        // `bk` inherits `oj_b`'s promotion and CAN be NULL. Live PG: NULL. Before
        // the fix this inferred NOT NULL (the base lookup dropped the promotion).
        let s = shape(
            &[OJ_A, OJ_B, OJ_C],
            "SELECT bk FROM oj_a LEFT JOIN oj_b ON oj_a.j = oj_b.j LEFT JOIN oj_c USING (bk)",
        )
        .expect("valid query");
        assert_eq!(s.columns, vec![col("bk", RustType::I32, true)]);

        // NATURAL merges the same common column by the same rule.
        let s = shape(
            &[OJ_A, OJ_B, OJ_C],
            "SELECT bk FROM oj_a LEFT JOIN oj_b ON oj_a.j = oj_b.j NATURAL LEFT JOIN oj_c",
        )
        .expect("valid query");
        assert_eq!(s.columns, vec![col("bk", RustType::I32, true)]);

        // A parenthesized left group whose inner LEFT JOIN promotes `oj_b`, then
        // merged: the pre-promotion snapshot captures the inner promotion too.
        let s = shape(
            &[OJ_A, OJ_B, OJ_C],
            "SELECT bk FROM (oj_a LEFT JOIN oj_b ON oj_a.j = oj_b.j) LEFT JOIN oj_c USING (bk)",
        )
        .expect("valid query");
        assert_eq!(s.columns, vec![col("bk", RustType::I32, true)]);
    }

    #[test]
    fn merged_right_contributor_with_inner_outer_join_is_nullable() {
        // The preserved side of a RIGHT/FULL merge is the RIGHT relation; when it
        // is itself an outer join (`(oj_a LEFT JOIN oj_b)`) its inner NULLs flow
        // into the merged key. Live PG: NULL. The fix defers THIS join's own
        // right-extension past the merge so the right side reports only its
        // INTERNAL promotion — enough to flip these, without over-nullabling a
        // plain right side (controls below).
        let s = shape(
            &[OJ_X, OJ_A, OJ_B],
            "SELECT bk FROM oj_x RIGHT JOIN (oj_a LEFT JOIN oj_b ON oj_a.j = oj_b.j) USING (bk)",
        )
        .expect("valid query");
        assert_eq!(s.columns, vec![col("bk", RustType::I32, true)]);

        let s = shape(
            &[OJ_X, OJ_A, OJ_B],
            "SELECT bk FROM oj_x FULL JOIN (oj_a LEFT JOIN oj_b ON oj_a.j = oj_b.j) USING (bk)",
        )
        .expect("valid query");
        assert_eq!(s.columns, vec![col("bk", RustType::I32, true)]);

        // The chained (`Some`) fold path reaches the same right side.
        let s = shape(
            &[OJ_C, OJ_X, OJ_A, OJ_B],
            "SELECT bk FROM oj_c JOIN oj_x USING (bk) \
             RIGHT JOIN (oj_a LEFT JOIN oj_b ON oj_a.j = oj_b.j) USING (bk)",
        )
        .expect("valid query");
        assert_eq!(s.columns, vec![col("bk", RustType::I32, true)]);
    }

    #[test]
    fn merged_over_outer_join_promotion_does_not_over_nullable() {
        // The regression guard: a merge whose contributors carry NO extra
        // promotion must keep its exact base-rule nullability — the fix must not
        // spuriously flip a provably-NOT-NULL merged key to Option.
        // INNER over two NOT NULL sides: matched equal key, never NULL.
        let s = shape(&[OJ_B, OJ_C], "SELECT bk FROM oj_b JOIN oj_c USING (bk)")
            .expect("valid query");
        assert_eq!(s.columns, vec![col("bk", RustType::I32, false)]);
        // FULL over two NOT NULL sides: an unmatched row's key is its own present
        // NOT NULL value — still never NULL.
        let s = shape(&[OJ_B, OJ_C], "SELECT bk FROM oj_b FULL JOIN oj_c USING (bk)")
            .expect("valid query");
        assert_eq!(s.columns, vec![col("bk", RustType::I32, false)]);
        // RIGHT over a NOT NULL preserved right side: never NULL.
        let s = shape(&[OJ_B, OJ_C], "SELECT bk FROM oj_b RIGHT JOIN oj_c USING (bk)")
            .expect("valid query");
        assert_eq!(s.columns, vec![col("bk", RustType::I32, false)]);
        // A LEFT merge whose PRESERVED left side is plainly NOT NULL (no earlier
        // promotion) stays NOT NULL — the fix reads the snapshot, which has no
        // promotion here.
        let s = shape(&[OJ_B, OJ_C], "SELECT bk FROM oj_b LEFT JOIN oj_c USING (bk)")
            .expect("valid query");
        assert_eq!(s.columns, vec![col("bk", RustType::I32, false)]);
    }

    #[test]
    fn merged_right_extension_still_promotes_later_references() {
        // Deferring THIS join's right-extension past the merge must NOT lose it:
        // a QUALIFIED reference to the right side's own column AFTER a LEFT/FULL
        // join must still see it as nullable (the right side was null-extended).
        // `oj_b.j` is NOT NULL at base; a LEFT JOIN null-extends `oj_b`, so a
        // qualified `oj_b.j` is nullable in the projection (had the deferred
        // extension been dropped, it would wrongly read NOT NULL).
        let s = shape(
            &[OJ_C, OJ_B],
            "SELECT oj_b.j FROM oj_c LEFT JOIN oj_b USING (bk)",
        )
        .expect("valid query");
        assert_eq!(s.columns, vec![col("j", RustType::I32, true)]);
    }

    #[test]
    fn resweep_broad_battery() {
        // VALID forms — must all be Ok (no new false-reject).
        let valids: &[(&[&str], &str)] = &[
            (&[USERS], "SELECT id, name, bio, age FROM users"),
            (&[USERS], "SELECT id AS x FROM users WHERE id = $1"),
            (&[USERS, ACCOUNTS], "SELECT users.name, accounts.balance FROM users INNER JOIN accounts ON accounts.user_id = users.id"),
            (&[USERS, ACCOUNTS], "SELECT users.name, accounts.balance FROM users LEFT JOIN accounts ON accounts.user_id = users.id"),
            (&[USERS, ACCOUNTS], "SELECT users.name FROM users JOIN accounts USING (id)"),
            (&[USERS, ACCOUNTS], "SELECT id FROM users JOIN accounts USING (id)"),
            (&[USERS, ACCOUNTS], "SELECT id FROM users NATURAL JOIN accounts"),
            (&[USERS, ACCOUNTS], "SELECT users.id, accounts.balance FROM users JOIN accounts USING (id)"),
            (&[ACCOUNTS], "SELECT id FROM accounts a JOIN accounts b USING (id) JOIN accounts c USING (id)"),
            (&[USERS], "INSERT INTO users (id, name) VALUES ($1, $2) RETURNING id"),
            (&[USERS], "INSERT INTO users (id, name) VALUES (1, 'a'), (2, 'b') RETURNING id"),
            (&[USERS], "INSERT INTO users VALUES (1, 'a', 'b', 2) RETURNING id"),
            (&[USERS], "INSERT INTO users VALUES (1) RETURNING id"),
            (&[USERS], "INSERT INTO users VALUES (1, 'a', 'b') RETURNING id"),
            (&[USERS], "INSERT INTO users VALUES (1, 'a', 'b', 2), (3, 'c', 'd', 4) RETURNING id"),
            (&[USERS], "INSERT INTO users SELECT id, name, bio, age FROM users RETURNING id"),
            (&[USERS], "INSERT INTO users SELECT id FROM users RETURNING id"),
            (&[USERS], "UPDATE users SET bio = $1 WHERE id = $2 RETURNING id"),
            (&[USERS], "DELETE FROM users WHERE id = $1 RETURNING id, name"),
            (&[USERS], "INSERT INTO users (id, name) VALUES (1, 'a') ON CONFLICT (id) DO NOTHING RETURNING id"),
            (&[USERS], "INSERT INTO users (id, name) VALUES ($1, $2) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name WHERE users.age > 0 RETURNING id"),
            (&[USERS], "INSERT INTO users (id, name) VALUES ($1, $2) ON CONFLICT (id) DO UPDATE SET name = $3 RETURNING id"),
            (&[USERS], "UPDATE users SET (name, bio) = ('a', 'b') WHERE id = 1 RETURNING id"),
            (&[USERS], "UPDATE users SET (name, bio) = (SELECT name, bio FROM users) WHERE id = 1 RETURNING id"),
            (&[USERS, ACCOUNTS], "UPDATE users SET age = a.balance FROM accounts a WHERE a.user_id = users.id RETURNING name"),
            (&[USERS], "INSERT INTO users (id, name, age) VALUES ($1, $2, DEFAULT) RETURNING id"),
            (&[USERS], "UPDATE users SET age = DEFAULT WHERE id = $1 RETURNING id"),
            (&[USERS], "INSERT INTO users (id, name) VALUES ($1, $2) ON CONFLICT (id) DO UPDATE SET age = DEFAULT RETURNING id"),
            (&[USERS], "INSERT INTO users (id, name) VALUES ($1, $2) ON CONFLICT (id) DO UPDATE SET (name, bio) = ('x', 'y') RETURNING id"),
            (&[USERS], "UPDATE users SET (name, age) = (DEFAULT, 1) WHERE id = 1 RETURNING id"),
        ];
        for (ddl, sql) in valids {
            if let Err(err) = shape(ddl, sql) {
                panic!("RESWEEP false-reject: {err:?}\n  SQL: {sql}");
            }
        }
        // LOUD forms — prior silent-accepts and genuine errors stay loud.
        let louds: &[(&[&str], &str)] = &[
            (&[USERS], "INSERT INTO users VALUES (1, 2, 3, 4, 5) RETURNING id"),
            (&[USERS], "INSERT INTO users VALUES (1, 2, 3, 4), (5, 6) RETURNING id"),
            (&[USERS], "INSERT INTO users SELECT id, name, bio, age, id FROM users RETURNING id"),
            (&[USERS], "INSERT INTO users (id, name) VALUES (1) RETURNING id"),
            (&[USERS], "INSERT INTO users (id) VALUES (1, 2) RETURNING id"),
            (&[USERS, ACCOUNTS], "SELECT id FROM users INNER JOIN accounts ON accounts.user_id = users.id"),
            (&[USERS, ACCOUNTS], "SELECT id FROM users, accounts a JOIN accounts b USING (id)"),
            (&[USERS, ACCOUNTS], "SELECT id FROM accounts a JOIN accounts b USING (id), users"),
            (&[USERS], "SELECT nope FROM users"),
            (&[USERS], "SELECT * FROM users"),
            (&[USERS, ACCOUNTS], "SELECT users.name FROM users JOIN accounts USING (nonexistent)"),
            (&[USERS], "INSERT INTO users (id, name) VALUES (1, 'a') ON CONFLICT (nonexistent) DO NOTHING RETURNING id"),
            (&[USERS], "INSERT INTO users (id, name) VALUES (1, 'a') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.bogus RETURNING id"),
            (&[USERS], "INSERT INTO users (id, name) VALUES (1, 'a') ON CONFLICT (id) DO UPDATE SET typo = 1 RETURNING id"),
            (&[USERS], "UPDATE users SET (name, bio) = ('a') WHERE id = 1 RETURNING id"),
            (&[USERS], "UPDATE users SET (name, bio) = (SELECT name FROM users) WHERE id = 1 RETURNING id"),
            (&[USERS], "INSERT INTO users (id, name) VALUES (1, 'a') ON CONFLICT (id) DO UPDATE SET (name, bio) = ROW('x') RETURNING id"),
            (&[USERS], "INSERT INTO users (id, name) VALUES (1, 'a') ON CONFLICT (id) DO UPDATE SET (name) = ('x') RETURNING id"),
            (&[USERS], "INSERT INTO users (id, age) VALUES (1, DEFAULT + 1) RETURNING id"),
            (&[USERS], "UPDATE users SET age = 1 WHERE id = DEFAULT RETURNING id"),
            (&[USERS], "SELECT default FROM users"),
            (&[USERS, ACCOUNTS], "UPDATE users SET age = a.balance FROM nosuch a WHERE a.user_id = users.id RETURNING name"),
            (&[USERS, ACCOUNTS], "DELETE FROM users USING accounts WHERE accounts.user_id = users.id RETURNING id"),
        ];
        for (ddl, sql) in louds {
            if shape(ddl, sql).is_ok() {
                panic!("RESWEEP silent-accept: SQL accepted that must be loud\n  SQL: {sql}");
            }
        }
    }

    // ── ON CONFLICT existence validation (loud both directions) ─────────

    #[test]
    fn on_conflict_target_typo_is_loud() {
        // ON CONFLICT (nonexistent): the conflict target names a column that
        // does not exist — loud, never a silently-accepted insert.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') \
             ON CONFLICT (nonexistent) DO NOTHING RETURNING id",
        )
        .expect_err("typo conflict target must be loud");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got {err:?}");
    }

    #[test]
    fn on_conflict_do_update_set_target_typo_is_loud() {
        // DO UPDATE SET typo=.. : the SET target column does not exist on the
        // target table — loud.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') \
             ON CONFLICT (id) DO UPDATE SET typo = 1 RETURNING id",
        )
        .expect_err("typo SET target must be loud");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got {err:?}");
    }

    #[test]
    fn on_conflict_do_update_set_value_typo_is_loud() {
        // SET name = typo : the value references an unknown column — loud.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') \
             ON CONFLICT (id) DO UPDATE SET name = typo RETURNING id",
        )
        .expect_err("typo SET value must be loud");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got {err:?}");
    }

    #[test]
    fn on_conflict_do_update_excluded_typo_is_loud() {
        // SET name = EXCLUDED.bogus : EXCLUDED exposes the target's columns, so
        // EXCLUDED.bogus (no such column) is loud — matching PostgreSQL's
        // "column excluded.bogus does not exist".
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') \
             ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.bogus RETURNING id",
        )
        .expect_err("EXCLUDED.bogus must be loud");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got {err:?}");
    }

    #[test]
    fn on_conflict_do_update_where_typo_is_loud() {
        // DO UPDATE ... WHERE typo>0 : the WHERE references an unknown column —
        // loud.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') \
             ON CONFLICT (id) DO UPDATE SET name = 'x' WHERE typo > 0 RETURNING id",
        )
        .expect_err("typo in DO UPDATE WHERE must be loud");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got {err:?}");
    }

    #[test]
    fn on_conflict_do_update_unqualified_shared_col_is_ambiguous() {
        // A bare `age` in the DO UPDATE WHERE is ambiguous: both the target and
        // EXCLUDED expose `age`. PostgreSQL rejects this ("column reference
        // age is ambiguous"); so does the engine — never silently picking one.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') \
             ON CONFLICT (id) DO UPDATE SET name = 'x' WHERE age > 0 RETURNING id",
        )
        .expect_err("ambiguous bare column must be loud");
        assert!(matches!(err, InferError::AmbiguousColumn(_)), "got {err:?}");
    }

    #[test]
    fn on_conflict_on_constraint_is_loud_unsupported() {
        // A named-constraint target refers to a constraint, which the
        // column-only catalog does not model — loud accurate unsupported, never
        // accept-as-opaque (so the name is never silently unchecked).
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') \
             ON CONFLICT ON CONSTRAINT users_pkey DO NOTHING RETURNING id",
        )
        .expect_err("ON CONSTRAINT must be loud");
        assert!(
            matches!(err, InferError::UnsupportedStatement(_)),
            "got {err:?}"
        );
    }

    #[test]
    fn on_conflict_valid_do_update_is_ok() {
        // ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name WHERE users.age>0
        // -> Ok (verified Ok against live PostgreSQL).
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') \
             ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name \
             WHERE users.age > 0 RETURNING id",
        )
        .expect("valid ON CONFLICT DO UPDATE must be Ok");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn on_conflict_do_nothing_is_ok() {
        shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES (1, 'a') \
             ON CONFLICT (id) DO NOTHING RETURNING id",
        )
        .expect("ON CONFLICT (id) DO NOTHING must be Ok");
    }

    #[test]
    fn on_conflict_do_update_no_target_is_loud() {
        // INSERT ... ON CONFLICT DO UPDATE with NO conflict target is hard-
        // rejected by PostgreSQL ("ON CONFLICT DO UPDATE requires inference
        // specification or constraint name") — an update needs an arbiter and
        // the server will not infer one. (Verified loud against live
        // PostgreSQL.) It must be a loud OnConflictUpdateNoTarget, never the
        // silently-accepted update its assignments would otherwise become.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT DO UPDATE SET name = 'z' RETURNING id",
        )
        .expect_err("targetless ON CONFLICT DO UPDATE must be loud");
        assert!(
            matches!(err, InferError::OnConflictUpdateNoTarget),
            "expected OnConflictUpdateNoTarget, got: {err:?}"
        );
    }

    #[test]
    fn on_conflict_do_nothing_no_target_is_ok() {
        // ON CONFLICT DO NOTHING with NO target stays valid: PostgreSQL infers
        // the arbiter across every unique constraint and skips any conflicting
        // row. (Verified Ok against live PostgreSQL.) Only DO UPDATE needs a
        // target — DO NOTHING must NOT be falsely rejected.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT DO NOTHING RETURNING id",
        )
        .expect("targetless ON CONFLICT DO NOTHING must be Ok");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn on_conflict_target_do_update_is_ok() {
        // ON CONFLICT (id) DO UPDATE — a column-list target — supplies the
        // arbiter, so the DO UPDATE is valid. (Verified Ok against live
        // PostgreSQL.) The target check must not over-reach onto a targeted
        // update.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT (id) DO UPDATE SET name = 'z' RETURNING id",
        )
        .expect("ON CONFLICT (id) DO UPDATE must be Ok");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    // ── ON CONFLICT DO UPDATE param typing (no false-reject) ────────────

    #[test]
    fn on_conflict_do_update_set_param_types() {
        // DO UPDATE SET name = $3 -> Ok, and $3 types to the column (text).
        // The $1/$2 come from VALUES; $3 from the DO UPDATE value.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT (id) DO UPDATE SET name = $3 RETURNING id",
        )
        .expect("DO UPDATE SET param must type");
        assert_eq!(
            s.params,
            vec![RustType::I64, RustType::Text, RustType::Text]
        );
    }

    #[test]
    fn on_conflict_do_update_where_param_types() {
        // DO UPDATE ... WHERE users.age = $3 -> Ok, $3 types to age (int4).
        // The WHERE column is QUALIFIED (`users.age`); a bare `age` would be
        // ambiguous (both target + EXCLUDED expose it), matching PostgreSQL.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT (id) DO UPDATE SET name = 'x' \
             WHERE users.age = $3 RETURNING id",
        )
        .expect("DO UPDATE WHERE param must type");
        assert_eq!(s.params, vec![RustType::I64, RustType::Text, RustType::I32]);
    }

    #[test]
    fn on_conflict_do_update_excluded_param_types() {
        // DO UPDATE SET age = $3 where the value side references EXCLUDED in a
        // sibling assignment; the $3 still types from its own SET target.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT (id) DO UPDATE SET bio = EXCLUDED.bio, age = $3 RETURNING id",
        )
        .expect("DO UPDATE multi-assignment param must type");
        assert_eq!(s.params, vec![RustType::I64, RustType::Text, RustType::I32]);
    }

    // ── UPDATE tuple-SET arity (loud both directions) ───────────────────

    #[test]
    fn update_tuple_set_parenthesised_scalar_is_not_a_row_source() {
        // SET (name, bio) = ('a') : the right-hand side is a parenthesised
        // SCALAR (`Nested`), not a row source. PostgreSQL rejects this with
        // "source for a multiple-column UPDATE item must be a sub-SELECT or
        // ROW() expression" — it is NOT an arity mismatch (the engine never
        // reaches a value count), so it is the dedicated row-source error,
        // never a silently-padded single-value assignment.
        let err = shape(
            &[USERS],
            "UPDATE users SET (name, bio) = ('a') WHERE id = 1 RETURNING id",
        )
        .expect_err("2-target scalar source must be loud");
        assert!(
            matches!(err, InferError::UpdateSetSourceNotRow),
            "got {err:?}"
        );
    }

    #[test]
    fn update_tuple_set_matching_arity_is_ok() {
        // SET (name, bio) = ('a', 'b') : 2 targets, 2 values -> Ok.
        shape(
            &[USERS],
            "UPDATE users SET (name, bio) = ('a', 'b') WHERE id = 1 RETURNING id",
        )
        .expect("matching tuple arity must be Ok");
    }

    #[test]
    fn update_tuple_set_subquery_arity_mismatch_is_loud() {
        // SET (name, bio) = (SELECT name FROM users) : 2 targets, 1 projected
        // value — loud (PostgreSQL: "number of columns does not match number
        // of values").
        let err = shape(
            &[USERS],
            "UPDATE users SET (name, bio) = (SELECT name FROM users) \
             WHERE id = 1 RETURNING id",
        )
        .expect_err("tuple = (subquery) arity mismatch must be loud");
        assert!(
            matches!(
                err,
                InferError::UpdateSetArityMismatch {
                    targets: 2,
                    values: 1
                }
            ),
            "got {err:?}"
        );
    }

    #[test]
    fn update_tuple_set_subquery_matching_is_ok() {
        // SET (name, bio) = (SELECT name, bio FROM users) -> Ok.
        shape(
            &[USERS],
            "UPDATE users SET (name, bio) = (SELECT name, bio FROM users) \
             WHERE id = 1 RETURNING id",
        )
        .expect("matching subquery arity must be Ok");
    }

    #[test]
    fn update_tuple_set_row_constructor_arity_is_checked() {
        // ROW('a') for 2 targets is loud; ROW('a','b') is Ok.
        let err = shape(
            &[USERS],
            "UPDATE users SET (name, bio) = ROW('a') WHERE id = 1 RETURNING id",
        )
        .expect_err("ROW(1) for 2 targets must be loud");
        assert!(
            matches!(
                err,
                InferError::UpdateSetArityMismatch {
                    targets: 2,
                    values: 1
                }
            ),
            "got {err:?}"
        );
        shape(
            &[USERS],
            "UPDATE users SET (name, bio) = ROW('a', 'b') WHERE id = 1 RETURNING id",
        )
        .expect("ROW(2) for 2 targets must be Ok");
    }

    // ── tuple-SET row-source rule (RHS must be a row source) ─────────────
    //
    // Cross-checked against live PostgreSQL: a multi-column `SET (a, ...) =
    // <rhs>` requires the RHS to be a ROW SOURCE — a row constructor `(v, ...)`,
    // a `ROW(...)`, or a sub-`SELECT`. A parenthesised SCALAR is not a row
    // source even for a single-column tuple target.

    #[test]
    fn update_single_tuple_target_scalar_source_is_not_a_row() {
        // SET (name) = ('a') : a single-column tuple target with a
        // parenthesised scalar RHS. PostgreSQL rejects this with "source for a
        // multiple-column UPDATE item must be a sub-SELECT or ROW()
        // expression" — the parens group ONE value, which is not a row source.
        let err = shape(
            &[USERS],
            "UPDATE users SET (name) = ('a') WHERE id = 1 RETURNING id",
        )
        .expect_err("single-tuple scalar source must be loud");
        assert!(
            matches!(err, InferError::UpdateSetSourceNotRow),
            "got {err:?}"
        );
    }

    #[test]
    fn update_single_tuple_target_default_source_is_not_a_row() {
        // SET (name) = (DEFAULT) : the parenthesised DEFAULT is still a single
        // grouped value, not a row source. PostgreSQL rejects it as a
        // row-source error (the row-source check runs before DEFAULT matters).
        let err = shape(
            &[USERS],
            "UPDATE users SET (name) = (DEFAULT) WHERE id = 1 RETURNING id",
        )
        .expect_err("single-tuple DEFAULT scalar source must be loud");
        assert!(
            matches!(err, InferError::UpdateSetSourceNotRow),
            "got {err:?}"
        );
    }

    #[test]
    fn update_single_tuple_target_two_value_row_is_arity_mismatch() {
        // SET (name) = ('a', 'b') : the RHS IS a row source (a 2-element row
        // constructor), so this passes the row-source check and is an ARITY
        // mismatch (1 target, 2 values) — PostgreSQL: "number of columns does
        // not match number of values".
        let err = shape(
            &[USERS],
            "UPDATE users SET (name) = ('a', 'b') WHERE id = 1 RETURNING id",
        )
        .expect_err("single-tuple 2-value row must be loud arity");
        assert!(
            matches!(
                err,
                InferError::UpdateSetArityMismatch {
                    targets: 1,
                    values: 2
                }
            ),
            "got {err:?}"
        );
    }

    #[test]
    fn update_tuple_target_nested_subquery_source_is_ok() {
        // SET (name) = ((SELECT name FROM users)) : the inner parens around a
        // sub-SELECT are grouping; the RHS is still a single-column sub-SELECT
        // row source matching the single target. PostgreSQL accepts this.
        shape(
            &[USERS],
            "UPDATE users SET (name) = ((SELECT name FROM users)) WHERE id = 1 RETURNING id",
        )
        .expect("nested sub-SELECT row source must be Ok");
    }

    #[test]
    fn update_tuple_target_nested_row_source_is_ok() {
        // SET (name) = (ROW('a')) : the outer parens group a `ROW(...)` row
        // source of arity 1, matching the single target. PostgreSQL accepts it.
        shape(
            &[USERS],
            "UPDATE users SET (name) = (ROW('a')) WHERE id = 1 RETURNING id",
        )
        .expect("nested ROW row source must be Ok");
    }

    #[test]
    fn update_tuple_set_default_in_row_cells_is_ok() {
        // SET (name, age) = (DEFAULT, 1) : the row constructor's cells are
        // value positions, so a top-level DEFAULT in a cell is accepted (the
        // column supplies its default). PostgreSQL accepts this.
        shape(
            &[USERS],
            "UPDATE users SET (name, age) = (DEFAULT, 1) WHERE id = 1 RETURNING id",
        )
        .expect("DEFAULT in tuple-source cell must be Ok");
        shape(
            &[USERS],
            "UPDATE users SET (name, age) = (DEFAULT, DEFAULT) WHERE id = 1 RETURNING id",
        )
        .expect("all-DEFAULT tuple source must be Ok");
    }

    #[test]
    fn update_tuple_set_default_in_row_function_cells_is_ok() {
        // SET (name, age) = ROW(DEFAULT, 1) : a ROW(...)'s positional arguments
        // are value cells; a top-level DEFAULT there is accepted by PostgreSQL.
        shape(
            &[USERS],
            "UPDATE users SET (name, age) = ROW(DEFAULT, 1) WHERE id = 1 RETURNING id",
        )
        .expect("DEFAULT in ROW source cell must be Ok");
    }

    #[test]
    fn update_tuple_set_nested_default_in_cell_is_loud() {
        // SET (name, age) = (name, DEFAULT + 1) : the DEFAULT is NESTED inside
        // a `DEFAULT + 1` cell, not a top-level value marker. PostgreSQL
        // rejects it ("DEFAULT is not allowed in this context"); the engine
        // matches with the precise DefaultNotAllowed diagnostic.
        let err = shape(
            &[USERS],
            "UPDATE users SET (name, age) = (name, DEFAULT + 1) WHERE id = 1 RETURNING id",
        )
        .expect_err("nested DEFAULT in tuple cell must be loud");
        assert!(matches!(err, InferError::DefaultNotAllowed), "got {err:?}");
    }

    // ── ON CONFLICT DO UPDATE tuple-SET (same row-source + arity rule) ───

    #[test]
    fn on_conflict_tuple_set_row_constructor_arity_is_checked() {
        // ON CONFLICT ... DO UPDATE SET (name, bio) = ROW('x') : ROW(1) for 2
        // targets is loud arity (PostgreSQL: "number of columns does not match
        // number of values") — the on-conflict path now runs the SAME arity
        // check as a plain UPDATE.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT (id) DO UPDATE SET (name, bio) = ROW('x') RETURNING id",
        )
        .expect_err("on-conflict ROW(1) for 2 targets must be loud");
        assert!(
            matches!(
                err,
                InferError::UpdateSetArityMismatch {
                    targets: 2,
                    values: 1
                }
            ),
            "got {err:?}"
        );
    }

    #[test]
    fn on_conflict_tuple_set_scalar_source_is_not_a_row() {
        // ON CONFLICT ... DO UPDATE SET (name) = ('x') : a parenthesised scalar
        // is not a row source. PostgreSQL rejects it identically to a plain
        // UPDATE ("source ... must be a sub-SELECT or ROW() expression").
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT (id) DO UPDATE SET (name) = ('x') RETURNING id",
        )
        .expect_err("on-conflict scalar source must be loud");
        assert!(
            matches!(err, InferError::UpdateSetSourceNotRow),
            "got {err:?}"
        );
    }

    #[test]
    fn on_conflict_tuple_set_matching_row_is_ok() {
        // ON CONFLICT ... DO UPDATE SET (name, bio) = ('x', 'y') : a matching
        // 2-element row source -> Ok ($1, $2 still type from the VALUES row).
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT (id) DO UPDATE SET (name, bio) = ('x', 'y') RETURNING id",
        )
        .expect("on-conflict matching tuple source must be Ok");
        assert_eq!(s.params, vec![RustType::I64, RustType::Text]);
    }

    // ── DEFAULT value keyword (accept in value positions, loud elsewhere) ─
    //
    // Cross-checked against live PostgreSQL: DEFAULT is a value-position marker
    // (INSERT VALUES cell, UPDATE/ON CONFLICT SET value); a `$N` sharing the
    // row still types by position. DEFAULT nested in an expression or in a
    // non-value position is rejected ("DEFAULT is not allowed in this
    // context").

    #[test]
    fn insert_values_default_alone_with_param_types_by_position() {
        // INSERT ... VALUES ($1, $2, DEFAULT) : DEFAULT contributes no param,
        // but $1/$2 still type from columns id/name by position.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name, age) VALUES ($1, $2, DEFAULT) RETURNING id",
        )
        .expect("INSERT VALUES with DEFAULT must be Ok");
        assert_eq!(s.params, vec![RustType::I64, RustType::Text]);
    }

    #[test]
    fn insert_values_default_with_literal_is_ok() {
        // INSERT ... VALUES ($1, 'lit', DEFAULT) : DEFAULT alongside a literal
        // and a param; the param still types by position.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name, age) VALUES ($1, 'lit', DEFAULT) RETURNING id",
        )
        .expect("INSERT VALUES DEFAULT with literal must be Ok");
        assert_eq!(s.params, vec![RustType::I64]);
    }

    #[test]
    fn insert_values_default_multi_row_types_all_params() {
        // Multi-row VALUES with DEFAULT in different positions; every $N still
        // types from the column at its row position (PostgreSQL: parameter
        // types {bigint, text, bigint, integer}).
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name, age) \
             VALUES ($1, $2, DEFAULT), ($3, DEFAULT, $4) RETURNING id",
        )
        .expect("multi-row VALUES with DEFAULT must be Ok");
        assert_eq!(
            s.params,
            vec![RustType::I64, RustType::Text, RustType::I64, RustType::I32]
        );
    }

    #[test]
    fn update_set_default_value_is_ok() {
        // UPDATE ... SET age = DEFAULT : a single-column SET value position;
        // DEFAULT is accepted, the $1 in WHERE still types.
        let s = shape(
            &[USERS],
            "UPDATE users SET age = DEFAULT WHERE id = $1 RETURNING id",
        )
        .expect("UPDATE SET col = DEFAULT must be Ok");
        assert_eq!(s.params, vec![RustType::I64]);
    }

    #[test]
    fn on_conflict_set_default_value_is_ok() {
        // ON CONFLICT ... DO UPDATE SET age = DEFAULT : a value position;
        // DEFAULT accepted, $1/$2 type from the VALUES row.
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT (id) DO UPDATE SET age = DEFAULT RETURNING id",
        )
        .expect("ON CONFLICT DO UPDATE SET col = DEFAULT must be Ok");
        assert_eq!(s.params, vec![RustType::I64, RustType::Text]);
    }

    #[test]
    fn default_nested_in_value_cell_is_loud() {
        // INSERT ... VALUES ($1, DEFAULT + 1) : DEFAULT nested inside an
        // arithmetic expression is NOT a top-level marker. PostgreSQL rejects
        // it ("DEFAULT is not allowed in this context"); the engine matches
        // with the precise DefaultNotAllowed diagnostic.
        let err = shape(
            &[USERS],
            "INSERT INTO users (id, age) VALUES ($1, DEFAULT + 1) RETURNING id",
        )
        .expect_err("DEFAULT + 1 in a value cell must be loud");
        assert!(matches!(err, InferError::DefaultNotAllowed), "got {err:?}");
    }

    #[test]
    fn default_in_where_is_loud() {
        // UPDATE ... WHERE id = DEFAULT : a WHERE predicate is NOT a value
        // position. PostgreSQL rejects DEFAULT here; the engine matches with
        // the precise DefaultNotAllowed diagnostic.
        let err = shape(
            &[USERS],
            "UPDATE users SET age = 1 WHERE id = DEFAULT RETURNING id",
        )
        .expect_err("DEFAULT in WHERE must be loud");
        assert!(matches!(err, InferError::DefaultNotAllowed), "got {err:?}");
    }

    #[test]
    fn default_in_returning_is_loud() {
        // UPDATE ... RETURNING DEFAULT : a projection is NOT a value position.
        // PostgreSQL rejects DEFAULT here; the engine matches with the precise
        // DefaultNotAllowed diagnostic.
        let err = shape(
            &[USERS],
            "UPDATE users SET age = 1 WHERE id = $1 RETURNING DEFAULT",
        )
        .expect_err("DEFAULT in RETURNING must be loud");
        assert!(matches!(err, InferError::DefaultNotAllowed), "got {err:?}");
    }

    #[test]
    fn default_in_standalone_values_subquery_is_loud() {
        // A VALUES list nested inside a FROM subquery is NOT a direct INSERT
        // value source. PostgreSQL rejects DEFAULT there ("DEFAULT is not
        // allowed in this context"); the engine keeps it loud (only the direct
        // INSERT VALUES rows accept the keyword) with the precise
        // DefaultNotAllowed diagnostic.
        let err = shape(&[USERS], "SELECT x FROM (VALUES (1), (DEFAULT)) v(x)")
            .expect_err("DEFAULT in a standalone VALUES must be loud");
        assert!(matches!(err, InferError::DefaultNotAllowed), "got {err:?}");
    }

    #[test]
    fn quoted_default_column_resolves_normally() {
        // A double-quoted "default" is a genuine column reference (PostgreSQL
        // preserves the case of a quoted identifier), NOT the DEFAULT keyword.
        // Against a table that HAS a column named `default`, it resolves; the
        // keyword special-casing only fires for the UNQUOTED marker.
        const T: &str =
            "CREATE TABLE q (id BIGINT PRIMARY KEY, \"default\" INT NOT NULL)";
        let s = shape(&[T], "SELECT \"default\" FROM q")
            .expect("quoted \"default\" column must resolve");
        assert_eq!(s.columns, vec![col("default", RustType::I32, false)]);
        // And as a SET value position it still resolves as a column reference,
        // not silently swallowed as the keyword.
        shape(
            &[T],
            "UPDATE q SET id = \"default\" WHERE id = $1 RETURNING id",
        )
        .expect("quoted \"default\" as a SET value must resolve as a column");
    }

    #[test]
    fn unquoted_default_in_projection_is_loud_default_not_allowed() {
        // A bare unquoted `default` in a non-value position (a projection) is
        // the reserved DEFAULT keyword (it can never be a column name in
        // PostgreSQL), so it is rejected with the precise "DEFAULT is not
        // allowed in this context" diagnostic — exactly as the live server
        // does, never a misleading unknown-column error.
        let err = shape(&[USERS], "SELECT default FROM users")
            .expect_err("bare default in projection must be loud");
        assert!(matches!(err, InferError::DefaultNotAllowed), "got {err:?}");
    }

    // ── UPDATE ... FROM (accept valid; accurate diagnostics) ────────────

    #[test]
    fn update_from_valid_is_ok() {
        // UPDATE users SET age = a.balance FROM accounts a WHERE a.user_id =
        // users.id -> Ok (the FROM relation `a` is modeled into scope, so its
        // columns resolve). RETURNING is unambiguous (target-only scope).
        let s = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users SET age = a.balance FROM accounts a \
             WHERE a.user_id = users.id RETURNING name",
        )
        .expect("valid UPDATE...FROM must be Ok");
        assert_eq!(s.columns, vec![col("name", RustType::Text, false)]);
    }

    #[test]
    fn update_from_value_typo_is_loud_and_accurate() {
        // A typo in a FROM-aware value (`a.nope`) is a loud UnknownColumn
        // naming the FROM relation `a` — accurate, not a misleading
        // UnknownRelation.
        let err = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users SET age = a.nope FROM accounts a \
             WHERE a.user_id = users.id RETURNING name",
        )
        .expect_err("typo in FROM-aware value must be loud");
        match err {
            InferError::UnknownColumn { relation, column } => {
                assert_eq!(relation, "a");
                assert_eq!(column, "nope");
            }
            other => panic!("expected UnknownColumn(a.nope), got {other:?}"),
        }
    }

    #[test]
    fn update_from_where_typo_is_loud() {
        // A typo in a FROM-aware WHERE is loud.
        let err = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users SET age = a.balance FROM accounts a \
             WHERE a.nope = users.id RETURNING name",
        )
        .expect_err("typo in FROM-aware WHERE must be loud");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got {err:?}");
    }

    #[test]
    fn update_from_nonexistent_relation_is_loud_unknown_relation() {
        // A nonexistent FROM relation is a loud UnknownRelation NAMING it —
        // never silently dropped, and never a misleading column error.
        let err = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users SET age = a.balance FROM nosuch a \
             WHERE a.user_id = users.id RETURNING name",
        )
        .expect_err("nonexistent FROM relation must be loud");
        match err {
            InferError::UnknownRelation(name) => assert_eq!(name, "nosuch"),
            other => panic!("expected UnknownRelation(nosuch), got {other:?}"),
        }
    }

    #[test]
    fn update_from_returning_from_relation_column_is_ok() {
        // RETURNING a FROM-relation column resolves against the full scope —
        // PostgreSQL accepts `RETURNING a.balance` in UPDATE...FROM.
        let s = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users SET age = a.balance FROM accounts a \
             WHERE a.user_id = users.id RETURNING a.balance",
        )
        .expect("RETURNING a FROM-relation column must be Ok");
        assert_eq!(s.columns, vec![col("balance", RustType::I32, false)]);
    }

    #[test]
    fn update_from_returning_ambiguous_bare_column_is_loud() {
        // A bare `id` present on BOTH users and accounts is ambiguous in
        // RETURNING — PostgreSQL rejects it ("column reference id is
        // ambiguous"); so does the engine, never silently resolving to the
        // target.
        let err = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users SET age = a.balance FROM accounts a \
             WHERE a.user_id = users.id RETURNING id",
        )
        .expect_err("ambiguous RETURNING column in UPDATE...FROM must be loud");
        assert!(matches!(err, InferError::AmbiguousColumn(_)), "got {err:?}");
    }

    #[test]
    fn update_from_param_types_against_full_scope() {
        // A `$N` compared to a FROM-relation column types from it.
        let s = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users SET age = a.balance FROM accounts a \
             WHERE a.user_id = $1 RETURNING name",
        )
        .expect("UPDATE...FROM param must type");
        assert_eq!(s.params, vec![RustType::I64]); // accounts.user_id is bigint
    }

    #[test]
    fn update_target_join_is_loud() {
        // A JOIN directly on the UPDATE target is not a standard PostgreSQL
        // UPDATE shape; reject it loudly rather than silently ignore the joined
        // relation.
        let err = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users JOIN accounts ON accounts.user_id = users.id \
             SET age = 1 RETURNING name",
        );
        // sqlparser may reject this syntactically (Parse) or the engine rejects
        // it as unsupported — either way it must be loud, never Ok.
        assert!(err.is_err(), "UPDATE target JOIN must be loud, got {err:?}");
    }

    // ── DML completeness guards (FIX-1 structural no-`..`) ──────────────

    #[test]
    fn delete_using_threads_relations_into_scope() {
        // DELETE ... USING is modeled exactly as UPDATE ... FROM: the USING
        // relations join the DELETE scope so the WHERE and RETURNING resolve
        // their columns. A fully-qualified, valid query is accepted.
        let s = shape(
            &[USERS, ACCOUNTS],
            "DELETE FROM users u USING accounts a WHERE a.user_id = u.id RETURNING u.id",
        )
        .expect("DELETE USING is modeled");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn delete_using_unqualified_ambiguous_column_is_loud() {
        // With both `users` and `accounts` in scope, an unqualified `RETURNING
        // id` is ambiguous (both have an `id`); PostgreSQL rejects it ("column
        // reference id is ambiguous"), and the engine — now that USING threads
        // the second relation into scope — raises the precise AmbiguousColumn,
        // not a blanket "unsupported".
        let err = shape(
            &[USERS, ACCOUNTS],
            "DELETE FROM users USING accounts WHERE accounts.user_id = users.id RETURNING id",
        )
        .expect_err("ambiguous RETURNING id must be loud");
        assert!(matches!(err, InferError::AmbiguousColumn(_)), "got {err:?}");
    }

    #[test]
    fn delete_using_cross_relation_typo_is_loud() {
        // A typo on a USING relation column is a loud UnknownColumn.
        let err = shape(
            &[USERS, ACCOUNTS],
            "DELETE FROM users u USING accounts a WHERE a.bogus = u.id RETURNING u.id",
        )
        .expect_err("USING column typo must be loud");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got {err:?}");
    }

    #[test]
    fn delete_using_nonexistent_relation_is_loud() {
        // A nonexistent USING relation is a loud UnknownRelation.
        let err = shape(
            &[USERS],
            "DELETE FROM users u USING nonexistent a WHERE a.x = u.id RETURNING u.id",
        )
        .expect_err("nonexistent USING relation must be loud");
        assert!(matches!(err, InferError::UnknownRelation(_)), "got {err:?}");
    }

    #[test]
    fn insert_or_action_is_loud_unsupported() {
        // INSERT OR REPLACE (SQLite extension) is not modeled; loud.
        let err = shape(
            &[USERS],
            "INSERT OR REPLACE INTO users (id, name) VALUES (1, 'a') RETURNING id",
        )
        .expect_err("INSERT OR REPLACE must be loud");
        assert!(
            matches!(err, InferError::UnsupportedStatement(_)),
            "got {err:?}"
        );
    }

    // ── corpus: ON CONFLICT + UPDATE-extension, both directions ─────────

    #[test]
    fn corpus_on_conflict_and_update_extensions_two_way() {
        // LOUD direction: every previously-silent-accept hole and genuine
        // error fails closed; never silently accepted.
        let loud: &[(&[&str], &str, &str)] = &[
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (nonexistent) DO NOTHING RETURNING id",
                "on-conflict-target-typo",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (id) DO UPDATE SET typo = 1 RETURNING id",
                "do-update-set-target-typo",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (id) DO UPDATE SET name = typo RETURNING id",
                "do-update-set-value-typo",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.bogus RETURNING id",
                "do-update-excluded-typo",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (id) DO UPDATE SET name = 'x' WHERE typo > 0 RETURNING id",
                "do-update-where-typo",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (id) DO UPDATE SET name = 'x' WHERE age > 0 RETURNING id",
                "do-update-where-ambiguous-bare-col",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT ON CONSTRAINT users_pkey DO NOTHING RETURNING id",
                "on-constraint-unsupported",
            ),
            (
                &[USERS],
                "UPDATE users SET (name, bio) = ('a') WHERE id = 1 RETURNING id",
                "tuple-set-scalar-source-not-row",
            ),
            (
                &[USERS],
                "UPDATE users SET (name) = ('a') WHERE id = 1 RETURNING id",
                "single-tuple-scalar-source-not-row",
            ),
            (
                &[USERS],
                "UPDATE users SET (name) = ('a', 'b') WHERE id = 1 RETURNING id",
                "single-tuple-two-value-arity",
            ),
            (
                &[USERS],
                "UPDATE users SET (name, bio) = (SELECT name FROM users) WHERE id = 1 RETURNING id",
                "tuple-set-subquery-mismatch",
            ),
            (
                &[USERS],
                "UPDATE users SET (name, bio) = ROW('a') WHERE id = 1 RETURNING id",
                "tuple-set-row-mismatch",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (id) DO UPDATE SET (name, bio) = ROW('x') RETURNING id",
                "on-conflict-tuple-set-row-mismatch",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (id) DO UPDATE SET (name) = ('x') RETURNING id",
                "on-conflict-tuple-set-scalar-source-not-row",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, age) VALUES (1, DEFAULT + 1) RETURNING id",
                "default-nested-in-value-cell",
            ),
            (
                &[USERS],
                "UPDATE users SET age = 1 WHERE id = DEFAULT RETURNING id",
                "default-in-where",
            ),
            (
                &[USERS],
                "UPDATE users SET age = 1 WHERE id = $1 RETURNING DEFAULT",
                "default-in-returning",
            ),
            (
                &[USERS],
                "SELECT x FROM (VALUES (1), (DEFAULT)) v(x)",
                "default-in-standalone-values",
            ),
            (
                &[USERS],
                "UPDATE users SET (name, age) = (name, DEFAULT + 1) WHERE id = 1 RETURNING id",
                "default-nested-in-tuple-cell",
            ),
            (
                &[USERS, ACCOUNTS],
                "UPDATE users SET age = a.nope FROM accounts a \
                 WHERE a.user_id = users.id RETURNING name",
                "update-from-value-typo",
            ),
            (
                &[USERS, ACCOUNTS],
                "UPDATE users SET age = a.balance FROM nosuch a \
                 WHERE a.user_id = users.id RETURNING name",
                "update-from-nonexistent-relation",
            ),
            (
                &[USERS, ACCOUNTS],
                "DELETE FROM users u USING accounts a WHERE a.bogus = u.id RETURNING u.id",
                "delete-using-cross-relation-typo",
            ),
        ];
        for (ddl, sql, name) in loud {
            if shape(ddl, sql).is_ok() {
                panic!("`{name}` was SILENTLY ACCEPTED (forbidden hole)\n  SQL: {sql}");
            }
        }
        // VALID direction: every valid ON CONFLICT / UPDATE-extension form is
        // accepted; never a false-reject.
        let ok: &[(&[&str], &str, &str)] = &[
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name \
                 WHERE users.age > 0 RETURNING id",
                "valid-do-update-excluded-where",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (id) DO NOTHING RETURNING id",
                "valid-do-nothing",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES ($1, $2) \
                 ON CONFLICT (id) DO UPDATE SET name = $3 RETURNING id",
                "valid-do-update-set-param",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES ($1, $2) \
                 ON CONFLICT (id) DO UPDATE SET name = 'x' \
                 WHERE users.age = $3 RETURNING id",
                "valid-do-update-where-param",
            ),
            (
                &[USERS],
                "UPDATE users SET (name, bio) = ('a', 'b') WHERE id = 1 RETURNING id",
                "valid-tuple-set-matching",
            ),
            (
                &[USERS],
                "UPDATE users SET (name, bio) = (SELECT name, bio FROM users) \
                 WHERE id = 1 RETURNING id",
                "valid-tuple-set-subquery-matching",
            ),
            (
                &[USERS, ACCOUNTS],
                "UPDATE users SET age = a.balance FROM accounts a \
                 WHERE a.user_id = users.id RETURNING name",
                "valid-update-from",
            ),
            (
                &[USERS, ACCOUNTS],
                "UPDATE users SET age = a.balance FROM accounts a \
                 WHERE a.user_id = $1 RETURNING name",
                "valid-update-from-param",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES (1, 'a') \
                 ON CONFLICT (id) DO UPDATE SET (name, bio) = ('x', 'y') RETURNING id",
                "valid-on-conflict-tuple-set-matching",
            ),
            (
                &[USERS],
                "UPDATE users SET (name) = ((SELECT name FROM users)) WHERE id = 1 RETURNING id",
                "valid-single-tuple-nested-subquery-source",
            ),
            (
                &[USERS],
                "UPDATE users SET (name) = (ROW('a')) WHERE id = 1 RETURNING id",
                "valid-single-tuple-nested-row-source",
            ),
            (
                &[USERS],
                "UPDATE users SET (name, age) = (DEFAULT, 1) WHERE id = 1 RETURNING id",
                "valid-tuple-set-default-cell",
            ),
            (
                &[USERS],
                "UPDATE users SET (name, age) = ROW(DEFAULT, 1) WHERE id = 1 RETURNING id",
                "valid-tuple-set-default-row-cell",
            ),
            // ── DEFAULT keyword in genuine value positions (with/without
            //    params, multi-row) — accepted; never a false reject. ──
            (
                &[USERS],
                "INSERT INTO users (id, name, age) VALUES (1, 'a', DEFAULT) RETURNING id",
                "valid-insert-values-default-no-param",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name, age) VALUES ($1, $2, DEFAULT) RETURNING id",
                "valid-insert-values-default-with-param",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name, age) \
                 VALUES ($1, $2, DEFAULT), ($3, DEFAULT, $4) RETURNING id",
                "valid-insert-values-default-multi-row",
            ),
            (
                &[USERS],
                "UPDATE users SET age = DEFAULT WHERE id = $1 RETURNING id",
                "valid-update-set-default",
            ),
            (
                &[USERS],
                "INSERT INTO users (id, name) VALUES ($1, $2) \
                 ON CONFLICT (id) DO UPDATE SET age = DEFAULT RETURNING id",
                "valid-on-conflict-set-default",
            ),
        ];
        for (ddl, sql, name) in ok {
            if let Err(err) = shape(ddl, sql) {
                panic!("`{name}` was wrongly REJECTED (false reject): {err:?}\n  SQL: {sql}");
            }
        }
    }

    // ── FROM-clause feature dimension ──────────────────────────────────

    #[test]
    fn derived_alias_list_renames_columns_positionally() {
        // The aliased names resolve to the projected columns by POSITION.
        let s = shape(
            &[USERS],
            "SELECT x, y FROM (SELECT id, name FROM users) AS t(x, y)",
        )
        .expect("aliased names resolve");
        assert_eq!(
            s.columns,
            vec![
                col("x", RustType::I64, false),
                col("y", RustType::Text, false),
            ]
        );
    }

    #[test]
    fn derived_alias_list_makes_original_names_unresolvable() {
        // After `t(x, y)` the projected `id` is renamed to `x`, so referencing
        // the ORIGINAL `id` is loud (PG: column "id" does not exist) — the
        // silent-accept hole is closed.
        let err = shape(
            &[USERS],
            "SELECT id FROM (SELECT id, name FROM users) AS t(x, y)",
        )
        .expect_err("original name no longer resolves");
        assert!(
            matches!(err, InferError::UnknownColumn { .. }),
            "got: {err:?}"
        );
    }

    #[test]
    fn derived_alias_list_renames_by_alias_not_source_name() {
        // The exposed name is the ALIAS, regardless of the inner output name.
        let s = shape(
            &[USERS],
            "SELECT x FROM (SELECT id AS x_src FROM users) t(x)",
        )
        .expect("alias resolves");
        assert_eq!(s.columns, vec![col("x", RustType::I64, false)]);
        // The inner output name `x_src` does NOT resolve through the alias.
        let err = shape(
            &[USERS],
            "SELECT x_src FROM (SELECT id AS x_src FROM users) t(x)",
        )
        .expect_err("inner name shadowed by alias");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got: {err:?}");
    }

    #[test]
    fn derived_alias_list_fewer_than_columns_keeps_trailing_original_names() {
        // PG renames the first N columns and leaves the rest with their
        // original names; `name` (position 2, unaliased) still resolves.
        let s = shape(
            &[USERS],
            "SELECT x, name FROM (SELECT id, name FROM users) AS t(x)",
        )
        .expect("trailing original name still resolves");
        assert_eq!(
            s.columns,
            vec![
                col("x", RustType::I64, false),
                col("name", RustType::Text, false),
            ]
        );
    }

    #[test]
    fn derived_alias_list_more_than_columns_is_loud() {
        // More aliases than the relation exposes is loud (PG: "table `t` has 2
        // columns available but 3 columns specified").
        let err = shape(
            &[USERS],
            "SELECT x FROM (SELECT id, name FROM users) AS t(x, y, z)",
        )
        .expect_err("too many aliases");
        assert!(
            matches!(
                err,
                InferError::AliasColumnCountExceedsRelation {
                    available: 2,
                    specified: 3,
                    ..
                }
            ),
            "got: {err:?}"
        );
    }

    #[test]
    fn alias_list_on_base_table_is_loud_accurate_unordered() {
        // A positional alias list on a base catalog table cannot be applied
        // faithfully (the catalog stores columns by name, not declaration
        // order); it is a loud, accurate error rather than a silent accept or
        // a misleading unknown relation. PG accepts this form, but the catalog
        // genuinely cannot model the positional rename.
        let err = shape(&[USERS], "SELECT a, b FROM users AS t(a, b)")
            .expect_err("base-table alias list is unordered-loud");
        assert!(
            matches!(err, InferError::AliasColumnsOnUnorderedRelation { .. }),
            "got: {err:?}"
        );
    }

    #[test]
    fn alias_list_on_transparent_select_star_is_loud_accurate() {
        // A transparent `SELECT *` subquery is catalog-backed, so an alias list
        // on it is the same unordered-loud case as a base table.
        let err = shape(
            &[USERS],
            "SELECT a FROM (SELECT * FROM users) AS t(a, b, c, d)",
        )
        .expect_err("transparent-star alias list is unordered-loud");
        assert!(
            matches!(err, InferError::AliasColumnsOnUnorderedRelation { .. }),
            "got: {err:?}"
        );
    }

    #[test]
    fn values_derived_table_types_and_alias_renames() {
        // A `(VALUES ...) AS t(p, q)` derived table types each cell and renames
        // by the alias list positionally.
        let s = shape(&[USERS], "SELECT p, q FROM (VALUES (1, 2)) AS t(p, q)")
            .expect("VALUES derived types");
        assert_eq!(
            s.columns,
            vec![
                col("p", RustType::I32, false),
                col("q", RustType::I32, false),
            ]
        );
    }

    #[test]
    fn values_top_level_query_types_default_names() {
        // A top-level `VALUES (1), (2)` projects `column1` typed by row
        // unification.
        let s = shape(&[USERS], "VALUES (1), (2)").expect("top-level VALUES");
        assert_eq!(s.columns, vec![col("column1", RustType::I32, false)]);
    }

    #[test]
    fn cte_defining_alias_list_renames_positionally() {
        let s = shape(
            &[USERS],
            "WITH t(a, b) AS (SELECT id, name FROM users) SELECT a, b FROM t",
        )
        .expect("CTE alias list renames");
        assert_eq!(
            s.columns,
            vec![
                col("a", RustType::I64, false),
                col("b", RustType::Text, false),
            ]
        );
    }

    #[test]
    fn cte_defining_alias_list_too_many_is_loud() {
        let err = shape(
            &[USERS],
            "WITH t(a, b, c) AS (SELECT id, name FROM users) SELECT a FROM t",
        )
        .expect_err("CTE alias list too many");
        assert!(
            matches!(
                err,
                InferError::AliasColumnCountExceedsRelation { available: 2, specified: 3, .. }
            ),
            "got: {err:?}"
        );
    }

    #[test]
    fn cte_referenced_with_alias_list_at_use_site_renames() {
        // Re-aliasing a CTE's columns at the FROM reference site (`FROM cte AS
        // x(p, q)`) renames its ordered column set positionally.
        let s = shape(
            &[USERS],
            "WITH t AS (SELECT id, name FROM users) SELECT p, q FROM t AS x(p, q)",
        )
        .expect("reference-site re-alias");
        assert_eq!(
            s.columns,
            vec![
                col("p", RustType::I64, false),
                col("q", RustType::Text, false),
            ]
        );
        // The original CTE names no longer resolve under the re-alias.
        let err = shape(
            &[USERS],
            "WITH t AS (SELECT id, name FROM users) SELECT id FROM t AS x(p, q)",
        )
        .expect_err("original name shadowed by re-alias");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got: {err:?}");
    }

    #[test]
    fn sibling_cte_reference_resolves_without_params() {
        // A later CTE referencing an earlier sibling resolves — even with ZERO
        // params (the param walker's CTE-body walk must thread the accumulating
        // sibling map, not rebuild it from the body alone).
        let s = shape(
            &[USERS],
            "WITH a AS (SELECT id FROM users), b AS (SELECT id FROM a) SELECT id FROM b",
        )
        .expect("sibling CTE resolves with no params");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
        assert!(s.params.is_empty());
    }

    #[test]
    fn sibling_cte_reference_resolves_with_param() {
        let s = shape(
            &[USERS],
            "WITH a AS (SELECT id FROM users), \
                  b AS (SELECT id FROM a WHERE id = $1) \
             SELECT id FROM b",
        )
        .expect("sibling CTE with param");
        assert_eq!(s.params, vec![RustType::I64]);
    }

    #[test]
    fn tuple_set_row_source_params_type_from_target_columns() {
        // A bare `$N` in a tuple-SET row constructor types from the target
        // column at the same position, on the plain-UPDATE path.
        let s = shape(
            &[USERS],
            "UPDATE users SET (name, bio) = ($1, $2) WHERE id = $3 RETURNING id",
        )
        .expect("tuple SET params typed");
        assert_eq!(s.params, vec![RustType::Text, RustType::Text, RustType::I64]);
    }

    #[test]
    fn tuple_set_row_constructor_params_type_from_target_columns() {
        // The `ROW(...)` form types identically.
        let s = shape(
            &[USERS],
            "UPDATE users SET (name, bio) = ROW($1, $2) WHERE id = $3 RETURNING id",
        )
        .expect("tuple SET ROW params typed");
        assert_eq!(s.params, vec![RustType::Text, RustType::Text, RustType::I64]);
    }

    #[test]
    fn on_conflict_tuple_set_params_type_from_target_columns() {
        let s = shape(
            &[USERS],
            "INSERT INTO users (id, name) VALUES ($1, $2) \
             ON CONFLICT (id) DO UPDATE SET (name, bio) = ($3, $4) RETURNING id",
        )
        .expect("ON CONFLICT tuple SET params typed");
        assert_eq!(
            s.params,
            vec![RustType::I64, RustType::Text, RustType::Text, RustType::Text]
        );
    }

    #[test]
    fn tuple_set_subquery_source_stays_context_typed() {
        // A sub-SELECT row source's cells type from the subselect's own
        // projection, not the target columns; a bare `$N` there has no column
        // context and fails closed (matching INSERT...SELECT).
        let err = shape(
            &[USERS],
            "UPDATE users SET (name, bio) = (SELECT $1, $2) WHERE id = $3 RETURNING id",
        )
        .expect_err("subquery-source bare params fail closed");
        assert!(
            matches!(err, InferError::ParamCastRequired { .. }),
            "got: {err:?}"
        );
    }

    #[test]
    fn lateral_outer_correlated_body_is_accepted() {
        // A valid outer-correlated LATERAL body resolves the outer relation
        // rather than a misleading UnknownRelation.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT u.id FROM users u, \
             LATERAL (SELECT a.balance FROM accounts a WHERE a.user_id = u.id) s",
        )
        .expect("comma LATERAL accepted");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn lateral_body_may_project_outer_column() {
        let s = shape(
            &[USERS],
            "SELECT s.uid FROM users u, LATERAL (SELECT u.id AS uid) s",
        )
        .expect("LATERAL projecting outer column");
        assert_eq!(s.columns, vec![col("uid", RustType::I64, false)]);
    }

    #[test]
    fn join_lateral_variants_are_accepted() {
        for join in ["CROSS JOIN LATERAL", "INNER JOIN LATERAL", "LEFT JOIN LATERAL"] {
            let on = if join.starts_with("CROSS") { "" } else { " ON true" };
            let sql = format!(
                "SELECT u.id FROM users u {join} \
                 (SELECT a.balance FROM accounts a WHERE a.user_id = u.id) s{on}"
            );
            if let Err(e) = shape(&[USERS, ACCOUNTS], &sql) {
                panic!("`{join}` wrongly rejected: {e:?}");
            }
        }
    }

    #[test]
    fn update_from_lateral_referencing_target_is_loud() {
        // A `LATERAL` body in an `UPDATE ... FROM` may reference PRIOR FROM
        // items but NOT the UPDATE target: PostgreSQL rejects it ("invalid
        // reference to FROM-clause entry for table `u`"). The target is
        // excluded from the lateral snapshot, so a reference to it is a loud,
        // accurate UnknownRelation on the target alias — never a silent accept.
        let err = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users u SET age = s.balance \
             FROM LATERAL (SELECT a.balance FROM accounts a WHERE a.user_id = u.id) s \
             RETURNING u.id",
        )
        .expect_err("UPDATE FROM LATERAL referencing the target is loud");
        assert!(matches!(err, InferError::UnknownRelation(_)), "got: {err:?}");
    }

    #[test]
    fn update_from_lateral_referencing_prior_from_item_is_ok() {
        // A `LATERAL` body referencing a PRIOR FROM item (not the target) is
        // accepted, exactly as PostgreSQL accepts it.
        shape(
            &[USERS, ACCOUNTS],
            "UPDATE users SET age = s.balance \
             FROM accounts a, LATERAL (SELECT a.balance) s \
             RETURNING users.id",
        )
        .expect("UPDATE FROM with a lateral body referencing a prior FROM item is ok");
    }

    #[test]
    fn update_from_nested_join_is_modeled() {
        // A parenthesized join in an UPDATE FROM clause is modeled (all nested
        // relations visible), matching PostgreSQL.
        shape(
            &[USERS, ACCOUNTS],
            "UPDATE users u SET age = a.balance \
             FROM (accounts a JOIN accounts a2 ON a.id = a2.id) \
             WHERE u.id = a.user_id RETURNING u.id",
        )
        .expect("UPDATE FROM nested join modeled");
    }

    #[test]
    fn update_from_nested_join_internal_typo_is_loud() {
        // A typo inside a parenthesized UPDATE-FROM join's ON predicate is loud.
        let err = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users u SET age = a.balance \
             FROM (accounts a JOIN accounts a2 ON a.id = a2.nope) \
             WHERE u.id = a.user_id RETURNING u.id",
        )
        .expect_err("UPDATE FROM nested join ON typo is loud");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got: {err:?}");
    }

    #[test]
    fn update_from_join_on_typo_is_loud() {
        // A typo in an UPDATE-FROM (non-parenthesized) join's ON predicate is
        // loud, matching PostgreSQL.
        let err = shape(
            &[USERS, ACCOUNTS],
            "UPDATE users u SET age = a.balance \
             FROM accounts a JOIN accounts a2 ON a.nope = a2.id \
             WHERE u.id = a.user_id RETURNING u.id",
        )
        .expect_err("UPDATE FROM join ON typo is loud");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got: {err:?}");
    }

    #[test]
    fn lateral_body_internal_typo_is_loud_and_accurate() {
        // A genuine typo against an outer relation INSIDE a lateral body is a
        // precise UnknownColumn on the outer relation, not a misleading
        // UnknownRelation on the outer alias.
        let err = shape(
            &[USERS, ACCOUNTS],
            "SELECT u.id FROM users u, \
             LATERAL (SELECT a.balance FROM accounts a WHERE a.user_id = u.nonexistent) s",
        )
        .expect_err("lateral typo is loud");
        assert!(
            matches!(err, InferError::UnknownColumn { .. }),
            "got: {err:?}"
        );
    }

    #[test]
    fn lateral_param_types_from_outer_column() {
        // A `$N` compared to an outer column inside a lateral body types from
        // that outer column.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT u.id FROM users u, \
             LATERAL (SELECT a.balance FROM accounts a \
                      WHERE a.user_id = u.id AND u.id = $1) s",
        )
        .expect("lateral param typed from outer");
        assert_eq!(s.params, vec![RustType::I64]);
    }

    #[test]
    fn table_function_in_from_is_loud_and_accurate() {
        // A table-valued function source names the form precisely, not a typo'd
        // relation.
        let err = shape(&[USERS], "SELECT g FROM generate_series(1, 10) AS g")
            .expect_err("table function is loud");
        match err {
            InferError::UnsupportedStatement(message) => {
                assert!(
                    message.contains("table function"),
                    "diagnostic must name the table function form: {message}"
                );
            }
            other => panic!("expected an accurate table-function diagnostic, got: {other:?}"),
        }
    }

    #[test]
    fn with_recursive_genuine_fixpoint_is_loud_and_names_the_cte() {
        // A genuine self-reference (`SELECT n + 1 FROM t` in t's own body) is
        // an unmodeled fixpoint: loud, and the diagnostic names the SPECIFIC
        // self-referencing CTE (`t`), never a false claim about an unrelated one.
        let err = shape(
            &[USERS],
            "WITH RECURSIVE t(n) AS \
                 (SELECT 1 UNION ALL SELECT n + 1 FROM t WHERE n < 5) \
             SELECT n FROM t",
        )
        .expect_err("recursive CTE is loud");
        match err {
            InferError::UnsupportedStatement(message) => {
                assert!(
                    message.contains("recursive CTE `t`"),
                    "diagnostic must name the self-referencing CTE: {message}"
                );
            }
            other => panic!("expected an accurate recursive-CTE diagnostic, got: {other:?}"),
        }
    }

    #[test]
    fn with_recursive_non_self_referencing_is_accepted() {
        // `RECURSIVE` only PERMITS self-reference; this CTE never recurses, so
        // the keyword is inert and PostgreSQL accepts it. The engine resolves
        // it as a plain CTE rather than falsely rejecting it as a fixpoint.
        let s = shape(
            &[USERS],
            "WITH RECURSIVE t AS (SELECT id FROM users) SELECT id FROM t",
        )
        .expect("non-recursing WITH RECURSIVE is a plain CTE");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn with_recursive_self_reference_inside_subquery_is_loud() {
        // The self-reference is buried in a derived-table subquery inside the
        // recursive term; the recursive scan must look through it.
        let err = shape(
            &[USERS],
            "WITH RECURSIVE t(n) AS \
                 (SELECT 1 UNION ALL SELECT n + 1 FROM (SELECT n FROM t) s WHERE n < 5) \
             SELECT n FROM t",
        )
        .expect_err("nested self-reference is loud");
        match err {
            InferError::UnsupportedStatement(message) => {
                assert!(
                    message.contains("recursive CTE `t`"),
                    "diagnostic must name the self-referencing CTE: {message}"
                );
            }
            other => panic!("expected an accurate recursive-CTE diagnostic, got: {other:?}"),
        }
    }

    #[test]
    fn unnest_table_source_is_loud_and_accurate() {
        let err = shape(&[USERS], "SELECT u.v FROM UNNEST(ARRAY[1, 2]) AS u(v)")
            .expect_err("UNNEST source is loud");
        match err {
            InferError::UnsupportedStatement(message) => {
                assert!(message.contains("UNNEST"), "diagnostic must name UNNEST: {message}");
            }
            other => panic!("expected an accurate UNNEST diagnostic, got: {other:?}"),
        }
    }

    #[test]
    fn tablesample_with_explicit_columns_is_accepted() {
        // TABLESAMPLE does not change the row's column types, so a SELECT of
        // named columns over a sampled table types normally.
        let s = shape(&[USERS], "SELECT id, name FROM users TABLESAMPLE BERNOULLI (10)")
            .expect("TABLESAMPLE accepted");
        assert_eq!(
            s.columns,
            vec![
                col("id", RustType::I64, false),
                col("name", RustType::Text, false),
            ]
        );
    }

    #[test]
    fn join_right_side_derived_with_alias_list_is_accepted() {
        // A JOIN whose right side is a derived table carrying its own column-
        // alias list resolves the renamed columns.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT a.id, t.x FROM accounts a \
             JOIN (SELECT id AS x FROM users) t(x) ON a.user_id = t.x",
        )
        .expect("join right derived with alias list");
        assert_eq!(
            s.columns,
            vec![
                col("id", RustType::I32, false),
                col("x", RustType::I64, false),
            ]
        );
    }

    #[test]
    fn corpus_from_clause_dimension_two_way() {
        // OK direction: every valid FROM-clause feature form is accepted.
        let ok: &[(&[&str], &str)] = &[
            (&[USERS], "SELECT x, y FROM (SELECT id, name FROM users) AS t(x, y)"),
            (&[USERS], "SELECT name FROM (SELECT id, name FROM users) AS t(x)"),
            (&[USERS], "SELECT p, q FROM (VALUES (1, 2)) AS t(p, q)"),
            (&[USERS], "VALUES (1), (2)"),
            (&[USERS], "WITH t(a, b) AS (SELECT id, name FROM users) SELECT a, b FROM t"),
            (
                &[USERS],
                "WITH a AS (SELECT id FROM users), b AS (SELECT id FROM a) SELECT id FROM b",
            ),
            (
                &[USERS, ACCOUNTS],
                "SELECT u.id FROM users u, \
                 LATERAL (SELECT a.balance FROM accounts a WHERE a.user_id = u.id) s",
            ),
            (
                &[USERS, ACCOUNTS],
                "SELECT u.id FROM users u CROSS JOIN LATERAL \
                 (SELECT a.balance FROM accounts a WHERE a.user_id = u.id) s",
            ),
            (
                &[USERS],
                "UPDATE users SET (name, bio) = ($1, $2) WHERE id = $3 RETURNING id",
            ),
        ];
        for (ddl, sql) in ok {
            if let Err(err) = shape(ddl, sql) {
                panic!("FROM-dimension valid form wrongly REJECTED: {err:?}\n  SQL: {sql}");
            }
        }

        // LOUD direction: every silent-accept hole and genuinely-unmodelable
        // form fails closed; never silently accepted, never misleading.
        let loud: &[(&[&str], &str)] = &[
            (&[USERS], "SELECT id FROM (SELECT id, name FROM users) AS t(x, y)"),
            (&[USERS], "SELECT x FROM (SELECT id, name FROM users) AS t(x, y, z)"),
            (&[USERS], "SELECT a, b FROM users AS t(a, b)"),
            (&[USERS], "SELECT a FROM (SELECT * FROM users) AS t(a, b, c, d)"),
            (&[USERS], "WITH t(a, b, c) AS (SELECT id, name FROM users) SELECT a FROM t"),
            (&[USERS], "SELECT g FROM generate_series(1, 10) AS g"),
            (
                &[USERS],
                "WITH RECURSIVE t(n) AS \
                     (SELECT 1 UNION ALL SELECT n + 1 FROM t WHERE n < 5) SELECT n FROM t",
            ),
            (&[USERS], "SELECT u.v FROM UNNEST(ARRAY[1, 2]) AS u(v)"),
            (
                &[USERS, ACCOUNTS],
                "SELECT u.id FROM users u, \
                 LATERAL (SELECT a.balance FROM accounts a WHERE a.user_id = u.nope) s",
            ),
        ];
        for (ddl, sql) in loud {
            if shape(ddl, sql).is_ok() {
                panic!("FROM-dimension invalid/unmodelable form wrongly ACCEPTED\n  SQL: {sql}");
            }
        }
    }

    // ── duplicate CTE name (FIX-2) ──────────────────────────────────────

    #[test]
    fn duplicate_cte_name_is_loud() {
        // PostgreSQL rejects two CTEs by one name ("WITH query name `t`
        // specified more than once"); a name-keyed map would silently keep the
        // last, so it is a loud, accurate error naming the duplicate.
        let err = shape(
            &[USERS, ACCOUNTS],
            "WITH t AS (SELECT id FROM users), t AS (SELECT id FROM accounts) \
             SELECT id FROM t",
        )
        .expect_err("duplicate CTE name is loud");
        match err {
            InferError::DuplicateCteName { name } => assert_eq!(name, "t"),
            other => panic!("expected DuplicateCteName(t), got {other:?}"),
        }
    }

    #[test]
    fn duplicate_cte_name_is_case_folded() {
        // Unquoted CTE names fold to lowercase, so `t` and `T` collide exactly
        // as PostgreSQL resolves them.
        let err = shape(
            &[USERS],
            "WITH t AS (SELECT id FROM users), T AS (SELECT id FROM users) \
             SELECT id FROM t",
        )
        .expect_err("case-folded duplicate CTE name is loud");
        assert!(matches!(err, InferError::DuplicateCteName { .. }), "got: {err:?}");
    }

    #[test]
    fn distinct_sibling_cte_names_are_ok() {
        // The dup check must not false-reject distinct sibling names (a later
        // CTE may reference an earlier one).
        let s = shape(
            &[USERS, ACCOUNTS],
            "WITH a AS (SELECT id FROM users), b AS (SELECT id FROM a) \
             SELECT id FROM b",
        )
        .expect("distinct sibling CTE names are ok");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    // ── ONLY inheritance modifier (FIX-3) ───────────────────────────────

    #[test]
    fn select_from_only_table_is_ok() {
        // `FROM ONLY users` resolves to `users` (ONLY does not change the column
        // shape), not a misleading UnknownRelation on `only`.
        let s = shape(&[USERS], "SELECT id, name FROM ONLY users").expect("FROM ONLY users ok");
        assert_eq!(
            s.columns,
            vec![
                col("id", RustType::I64, false),
                col("name", RustType::Text, false),
            ]
        );
    }

    #[test]
    fn select_from_only_qualified_reference_resolves_under_real_name() {
        // The real table name is the qualifier (`users.id`), as PostgreSQL
        // exposes it under `ONLY`.
        let s = shape(&[USERS], "SELECT users.id FROM ONLY users").expect("ok");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    #[test]
    fn update_only_table_is_ok() {
        let s = shape(&[USERS], "UPDATE ONLY users SET age = $1 WHERE id = $2 RETURNING id")
            .expect("UPDATE ONLY users ok");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
        assert_eq!(s.params, vec![RustType::I32, RustType::I64]);
    }

    #[test]
    fn delete_from_only_table_is_ok() {
        let s = shape(&[USERS], "DELETE FROM ONLY users WHERE id = $1 RETURNING id")
            .expect("DELETE FROM ONLY users ok");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
        assert_eq!(s.params, vec![RustType::I64]);
    }

    #[test]
    fn from_only_nonexistent_is_loud_naming_the_real_table() {
        // ONLY is unwrapped, then the REAL (missing) table is resolved, so the
        // diagnostic names `nonexistent`, never `only`.
        let err = shape(&[USERS], "SELECT id FROM ONLY nonexistent")
            .expect_err("FROM ONLY nonexistent is loud");
        match err {
            InferError::UnknownRelation(name) => assert_eq!(name, "nonexistent"),
            other => panic!("expected UnknownRelation(nonexistent), got {other:?}"),
        }
    }

    #[test]
    fn update_only_nonexistent_is_loud_naming_the_real_table() {
        let err = shape(&[USERS], "UPDATE ONLY nonexistent SET age = 1 RETURNING id")
            .expect_err("UPDATE ONLY nonexistent is loud");
        match err {
            InferError::UnknownRelation(name) => assert_eq!(name, "nonexistent"),
            other => panic!("expected UnknownRelation(nonexistent), got {other:?}"),
        }
    }

    #[test]
    fn quoted_only_table_still_resolves_as_a_real_relation() {
        // A QUOTED `"only"` is a real relation named `only`, NOT the modifier
        // (case-sensitive fold), so it resolves when the table exists.
        let only_ddl = "CREATE TABLE \"only\" (id BIGINT PRIMARY KEY)";
        let s = shape(&[only_ddl], "SELECT id FROM \"only\"").expect("quoted only table ok");
        assert_eq!(s.columns, vec![col("id", RustType::I64, false)]);
    }

    // ── parenthesized / nested join (FIX-4) ─────────────────────────────

    #[test]
    fn nested_join_is_modeled() {
        // `FROM (a JOIN b ON ..)` has the SAME column scope as the
        // un-parenthesized chain; all nested relations are visible.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT u.id, a.balance \
             FROM (users u JOIN accounts a ON a.user_id = u.id)",
        )
        .expect("nested join modeled");
        assert_eq!(
            s.columns,
            vec![
                col("id", RustType::I64, false),
                col("balance", RustType::I32, false),
            ]
        );
    }

    #[test]
    fn nested_join_left_outer_propagates_nullability() {
        // A parenthesized group on the nullable side of an outer LEFT JOIN
        // makes EVERY relation it contributes nullable (the group can be
        // absent), matching the un-parenthesized lattice.
        let s = shape(
            &[USERS, ACCOUNTS],
            "SELECT u.name, a.balance, accounts.balance AS b2 \
             FROM users u LEFT JOIN (accounts a JOIN accounts ON true) \
                 ON a.user_id = u.id",
        )
        .expect("nested join under LEFT JOIN ok");
        assert_eq!(s.columns[0], col("name", RustType::Text, false));
        // Both inner relations are on the nullable side of the outer LEFT JOIN.
        assert_eq!(s.columns[1], col("balance", RustType::I32, true));
        assert_eq!(s.columns[2], col("b2", RustType::I32, true));
    }

    #[test]
    fn nested_join_internal_typo_is_loud() {
        // A missing relation INSIDE the parentheses surfaces loudly, naming the
        // real culprit.
        let err = shape(
            &[USERS, ACCOUNTS],
            "SELECT u.id FROM (users u JOIN nonexistent a ON a.user_id = u.id)",
        )
        .expect_err("nested join internal typo is loud");
        match err {
            InferError::UnknownRelation(name) => assert_eq!(name, "nonexistent"),
            other => panic!("expected UnknownRelation(nonexistent), got {other:?}"),
        }
    }

    #[test]
    fn nested_join_internal_column_typo_is_loud() {
        let err = shape(
            &[USERS, ACCOUNTS],
            "SELECT u.id FROM (users u JOIN accounts a ON a.user_id = u.nope)",
        )
        .expect_err("nested join internal column typo is loud");
        assert!(matches!(err, InferError::UnknownColumn { .. }), "got: {err:?}");
    }

    #[test]
    fn aliased_nested_join_is_loud_and_accurate() {
        // An ALIAS on a parenthesized join merges its columns under one name and
        // hides the inner relation names — a column shape the catalog cannot
        // model faithfully, so it is a loud, accurate error naming the form.
        let err = shape(
            &[USERS, ACCOUNTS],
            "SELECT x.id FROM (users u JOIN accounts a ON a.user_id = u.id) AS x",
        )
        .expect_err("aliased nested join is loud");
        match err {
            InferError::UnsupportedStatement(message) => assert!(
                message.contains("parenthesized join") && message.contains("aliased `x`"),
                "diagnostic must name the aliased nested-join form: {message}"
            ),
            other => panic!("expected an accurate aliased-nested-join diagnostic, got {other:?}"),
        }
    }

